INSERT INTO _fields_wd1_plan (site_id, column_name, old_value, new_value, change_key, reason, evidence) VALUES
    ('0047ae41-af8e-44e1-b196-4035f5860554'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s001-rollback:0047ae41-af8e-44e1-b196-4035f5860554:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1500 - 500 BC'' restored on Gonnus', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0047ae41-af8e-44e1-b196-4035f5860554'::uuid, 'period_start', NULL, '-1000', 'fields-wd1-2026-09-26b-s001-rollback:0047ae41-af8e-44e1-b196-4035f5860554:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-1000'' restored on Gonnus', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0010)", "decision": "clear", "status": "MISSING", "reasoning": "The readable pages date only parts of the city (an Archaic wall, an apsidal temple whose original building is put in the 7th century BC) or say it flourished from the 6th to the 4th century BC, all in one text of the Archaeological Atlas of the Aegean copied by ToposText and Golden Greece; Wikipedia (any language) and Pleiades give no start date, so no two independent sources date the beginning of Gonnus as a site and the stored -1000 has no support.", "value_page": null}]'::jsonb),
    ('006294ae-548b-40ac-9271-03a017df7217'::uuid, 'geom', 'SRID=4326;POINT(-89.99583 17.57444)', '0101000020E6100000A13902D2497B56C07AFE81A62BA83140', 'fields-wd1-2026-09-26b-s001-rollback:006294ae-548b-40ac-9271-03a017df7217:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E6100000A13902D2497B56C07AFE81A62BA83140'' restored on El Tintal', '[{"source": "https://es.wikipedia.org/wiki/Zona_arqueol%C3%B3gica_de_El_Tintal", "url": "https://es.wikipedia.org/wiki/Zona_arqueol%C3%B3gica_de_El_Tintal", "quote": "17.57444, -89.99583", "outcome": "found"}, {"source": "https://www.geonames.org/3595993/sitio-arqueologico-el-tintal.html", "url": "https://www.geonames.org/3595993/sitio-arqueologico-el-tintal.html", "quote": "17.58046, -89.99641", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0075)", "decision": "replace", "status": "CONFLICT", "reasoning": "Spanish Wikipedia/Wikidata put El Tintal at 17.57444, -89.99583 and the GeoNames (GNS) entry ''Sitio Arqueológico El Tintal'' at 17.58046, -89.99641, 0.67 km apart and about 20 km south-west of El Mirador as the literature describes; the stored point lies about 11.8 km north-east of both, so it is replaced.", "value_page": null}]'::jsonb),
    ('006294ae-548b-40ac-9271-03a017df7217'::uuid, 'lat', '17.57444', '17.65691605256732', 'fields-wd1-2026-09-26b-s001-rollback:006294ae-548b-40ac-9271-03a017df7217:lat', 'rollback of fields-wd1-2026-09-26b-s001: lat ''17.65691605256732'' restored on El Tintal', '[{"source": "https://es.wikipedia.org/wiki/Zona_arqueol%C3%B3gica_de_El_Tintal", "url": "https://es.wikipedia.org/wiki/Zona_arqueol%C3%B3gica_de_El_Tintal", "quote": "17.57444, -89.99583", "outcome": "found"}, {"source": "https://www.geonames.org/3595993/sitio-arqueologico-el-tintal.html", "url": "https://www.geonames.org/3595993/sitio-arqueologico-el-tintal.html", "quote": "17.58046, -89.99641", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0075)", "decision": "replace", "status": "CONFLICT", "reasoning": "Spanish Wikipedia/Wikidata put El Tintal at 17.57444, -89.99583 and the GeoNames (GNS) entry ''Sitio Arqueológico El Tintal'' at 17.58046, -89.99641, 0.67 km apart and about 20 km south-west of El Mirador as the literature describes; the stored point lies about 11.8 km north-east of both, so it is replaced.", "value_page": null}]'::jsonb),
    ('006294ae-548b-40ac-9271-03a017df7217'::uuid, 'lon', '-89.99583', '-89.92638063638016', 'fields-wd1-2026-09-26b-s001-rollback:006294ae-548b-40ac-9271-03a017df7217:lon', 'rollback of fields-wd1-2026-09-26b-s001: lon ''-89.92638063638016'' restored on El Tintal', '[{"source": "https://es.wikipedia.org/wiki/Zona_arqueol%C3%B3gica_de_El_Tintal", "url": "https://es.wikipedia.org/wiki/Zona_arqueol%C3%B3gica_de_El_Tintal", "quote": "17.57444, -89.99583", "outcome": "found"}, {"source": "https://www.geonames.org/3595993/sitio-arqueologico-el-tintal.html", "url": "https://www.geonames.org/3595993/sitio-arqueologico-el-tintal.html", "quote": "17.58046, -89.99641", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0075)", "decision": "replace", "status": "CONFLICT", "reasoning": "Spanish Wikipedia/Wikidata put El Tintal at 17.57444, -89.99583 and the GeoNames (GNS) entry ''Sitio Arqueológico El Tintal'' at 17.58046, -89.99641, 0.67 km apart and about 20 km south-west of El Mirador as the literature describes; the stored point lies about 11.8 km north-east of both, so it is replaced.", "value_page": null}]'::jsonb),
    ('006294ae-548b-40ac-9271-03a017df7217'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s001-rollback:006294ae-548b-40ac-9271-03a017df7217:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 BC - 1 AD'' restored on El Tintal', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-600) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('006294ae-548b-40ac-9271-03a017df7217'::uuid, 'period_start', '-600', '-500', 'fields-wd1-2026-09-26b-s001-rollback:006294ae-548b-40ac-9271-03a017df7217:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-500'' restored on El Tintal', '[{"source": "https://www.scielo.org.mx/scielo.php?script=sci_arttext&pid=S0185-25742023000200011", "url": "https://www.scielo.org.mx/scielo.php?script=sci_arttext&pid=S0185-25742023000200011", "quote": "La investigación de este antiguo asentamiento maya se ha enfocado en sus diferentes sectores con el propósito de reconstruir de manera integral su ocupación desde aproximadamente 600 a. C. hasta 900-1000 d. C.", "outcome": "found"}, {"source": "https://www.guatemala.com/historias/sociedad/el-tintal-sitio-arqueologico-civilizacion-maya-peten-guatemala.html", "url": "https://www.guatemala.com/historias/sociedad/el-tintal-sitio-arqueologico-civilizacion-maya-peten-guatemala.html", "quote": "Pertenece al período Preclásico Medio y Tardío (1000 AC – 150 DC).", "outcome": "found"}, {"source": "https://es.wikipedia.org/wiki/Zona_arqueol%C3%B3gica_de_El_Tintal", "url": "https://es.wikipedia.org/wiki/Zona_arqueol%C3%B3gica_de_El_Tintal", "quote": "desde el periodo Preclásico Medio (1000 – 350 a. C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0075)", "decision": "replace", "status": "MISSING", "reasoning": "The directors of the El Tintal Archaeological Project (Acuña and Matute 2023, Estudios de Cultura Maya) date the occupation from about 600 BC, with the earliest architecture in the Late Bayo phase 600-350 BC; Guatemala.com and Spanish Wikipedia place the start in the Middle Preclassic (from 1000 BC), so the start lies in the 1500-500 BC bucket, not the stored 500 BC - 1 AD, and is replaced by the excavators'' year.", "value_page": null}]'::jsonb),
    ('00daa905-2060-4b9c-8369-eb5e6878f6a6'::uuid, 'period_name', NULL, '< 4500 BC', 'fields-wd1-2026-09-26b-s001-rollback:00daa905-2060-4b9c-8369-eb5e6878f6a6:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''< 4500 BC'' restored on Burnt Fen', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('00daa905-2060-4b9c-8369-eb5e6878f6a6'::uuid, 'period_start', NULL, '-8000', 'fields-wd1-2026-09-26b-s001-rollback:00daa905-2060-4b9c-8369-eb5e6878f6a6:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-8000'' restored on Burnt Fen', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0029)", "decision": "clear", "status": "MISSING", "reasoning": "Only the Suffolk HER dates the Burnt Fen finds (flint scatter, ''9700 BC? to 4000 BC?''); Wikipedia says only ''Mesolithic period'' without a year, so there are not two independent dated sources.", "value_page": null}]'::jsonb),
    ('00daa905-2060-4b9c-8369-eb5e6878f6a6'::uuid, 'site_type', 'Archaeological site', 'City/town/settlement', 'fields-wd1-2026-09-26b-s001-rollback:00daa905-2060-4b9c-8369-eb5e6878f6a6:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''City/town/settlement'' restored on Burnt Fen', '[{"source": "https://en.wikipedia.org/wiki/Burnt_Fen", "url": "https://en.wikipedia.org/wiki/Burnt_Fen", "quote": "The area shows a remarkable amount of archaeological findings of the Mesolithic period.", "outcome": "found"}, {"source": "https://heritage.suffolk.gov.uk/Monument/MSF9239", "url": "https://heritage.suffolk.gov.uk/Monument/MSF9239", "quote": "FLINT SCATTER? (Terminal Palaeolithic (Ahrensburgian, Long Blade) to Late Mesolithic - 9700 BC? to 4000 BC?)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0029)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe Burnt Fen as a fen area yielding Mesolithic flint finds (a possible flint scatter of stray finds), not a town or settlement; no more specific canonical type fits, so the generic Archaeological site replaces City/town/settlement.", "value_page": null}]'::jsonb),
    ('00f522ff-8e1b-4983-961c-ef6cb1ff27d1'::uuid, 'site_type', 'City', 'Megalithic structures', 'fields-wd1-2026-09-26b-s001-rollback:00f522ff-8e1b-4983-961c-ef6cb1ff27d1:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Megalithic structures'' restored on Olympos Antique City', '[{"source": "https://en.wikipedia.org/wiki/Olympus_(Lycia)", "url": "https://en.wikipedia.org/wiki/Olympus_(Lycia)", "quote": "is an ancient city in Lycia", "outcome": "found"}, {"source": "https://www.lycianmonuments.com/olympos/", "url": "https://www.lycianmonuments.com/olympos/", "quote": "Olympos is a port city located on the western coast of the Gulf of Antalya, approximately 16 km south of Phaselis.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0146)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Lycian Monuments both describe Olympos as a city (an ancient port city of Lycia and member of the Lycian League); nothing describes it as megalithic structures, so City replaces the stored type.", "value_page": null}]'::jsonb),
    ('010a33fa-5687-40f7-8dfd-a0042d78eab7'::uuid, 'geom', 'SRID=4326;POINT(16.469139 41.177056)', '0101000020E6100000A649A1D45781304071DBC88F219F4440', 'fields-wd1-2026-09-26b-s001-rollback:010a33fa-5687-40f7-8dfd-a0042d78eab7:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E6100000A649A1D45781304071DBC88F219F4440'' restored on Grotta di Santa Croce', '[{"source": "https://it.wikipedia.org/wiki/Grotta_di_Santa_Croce", "url": "https://it.wikipedia.org/wiki/Grotta_di_Santa_Croce", "quote": "41°10′37.4″N 16°28′08.9″E", "outcome": "found"}, {"source": "https://www.showcaves.com/english/it/showcaves/SantaCroce.html", "url": "https://www.showcaves.com/english/it/showcaves/SantaCroce.html", "quote": "41.1770556, 16.4691389", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0085)", "decision": "replace", "status": "CONFLICT", "reasoning": "Italian Wikipedia and Show Caves of the World both place the cave entrance in the Lama di Santa Croce about 7 km inland (41.17706, 16.46914); the stored point lies on the town of Bisceglie, about 8 km away, so it is replaced.", "value_page": null}]'::jsonb),
    ('010a33fa-5687-40f7-8dfd-a0042d78eab7'::uuid, 'lat', '41.177056', '41.24321172053795', 'fields-wd1-2026-09-26b-s001-rollback:010a33fa-5687-40f7-8dfd-a0042d78eab7:lat', 'rollback of fields-wd1-2026-09-26b-s001: lat ''41.24321172053795'' restored on Grotta di Santa Croce', '[{"source": "https://it.wikipedia.org/wiki/Grotta_di_Santa_Croce", "url": "https://it.wikipedia.org/wiki/Grotta_di_Santa_Croce", "quote": "41°10′37.4″N 16°28′08.9″E", "outcome": "found"}, {"source": "https://www.showcaves.com/english/it/showcaves/SantaCroce.html", "url": "https://www.showcaves.com/english/it/showcaves/SantaCroce.html", "quote": "41.1770556, 16.4691389", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0085)", "decision": "replace", "status": "CONFLICT", "reasoning": "Italian Wikipedia and Show Caves of the World both place the cave entrance in the Lama di Santa Croce about 7 km inland (41.17706, 16.46914); the stored point lies on the town of Bisceglie, about 8 km away, so it is replaced.", "value_page": null}]'::jsonb),
    ('010a33fa-5687-40f7-8dfd-a0042d78eab7'::uuid, 'lon', '16.469139', '16.505246438385846', 'fields-wd1-2026-09-26b-s001-rollback:010a33fa-5687-40f7-8dfd-a0042d78eab7:lon', 'rollback of fields-wd1-2026-09-26b-s001: lon ''16.505246438385846'' restored on Grotta di Santa Croce', '[{"source": "https://it.wikipedia.org/wiki/Grotta_di_Santa_Croce", "url": "https://it.wikipedia.org/wiki/Grotta_di_Santa_Croce", "quote": "41°10′37.4″N 16°28′08.9″E", "outcome": "found"}, {"source": "https://www.showcaves.com/english/it/showcaves/SantaCroce.html", "url": "https://www.showcaves.com/english/it/showcaves/SantaCroce.html", "quote": "41.1770556, 16.4691389", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0085)", "decision": "replace", "status": "CONFLICT", "reasoning": "Italian Wikipedia and Show Caves of the World both place the cave entrance in the Lama di Santa Croce about 7 km inland (41.17706, 16.46914); the stored point lies on the town of Bisceglie, about 8 km away, so it is replaced.", "value_page": null}]'::jsonb),
    ('010a33fa-5687-40f7-8dfd-a0042d78eab7'::uuid, 'period_name', '< 4500 BC', '1 - 500 AD', 'fields-wd1-2026-09-26b-s001-rollback:010a33fa-5687-40f7-8dfd-a0042d78eab7:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1 - 500 AD'' restored on Grotta di Santa Croce', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-150000) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('010a33fa-5687-40f7-8dfd-a0042d78eab7'::uuid, 'period_start', '-150000', '1', 'fields-wd1-2026-09-26b-s001-rollback:010a33fa-5687-40f7-8dfd-a0042d78eab7:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1'' restored on Grotta di Santa Croce', '[{"source": "https://www.fastionline.org/excavation/AIAC_2564", "url": "https://www.fastionline.org/excavation/AIAC_2564", "quote": "Date Range 150000 BC – 10000 BC 5000 BC – 3300 BC", "outcome": "found"}, {"source": "https://www.archeologiaviva.it/5050/puglia-la-stuoia-di-bisceglie/", "url": "https://www.archeologiaviva.it/5050/puglia-la-stuoia-di-bisceglie/", "quote": "Livelli di età olocenica con ceramiche pertinenti all’età del Bronzo medio iniziale (XVII-XVI sec. a.C.) e al Neolitico antico (V millennio a.C.)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0085)", "decision": "replace", "status": "MISSING", "reasoning": "FastiOnline dates the cave''s first (Middle Palaeolithic, Mousterian) occupation from 150000 BC; Archeologia Viva dates the upper Holocene levels to the Early Neolithic (5th millennium BC) and places the Mousterian levels with the Neanderthal femur below them, so the start lies well before 4500 BC, not in 1-500 AD.", "value_page": null}]'::jsonb),
    ('010c0b09-760b-44f6-ba68-1f0353c7b3e6'::uuid, 'geom', 'SRID=4326;POINT(-4.828834 36.872802)', '0101000020E6100000C6FA796BF66013C026CD83CD5F704240', 'fields-wd1-2026-09-26b-s001-rollback:010c0b09-760b-44f6-ba68-1f0353c7b3e6:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E6100000C6FA796BF66013C026CD83CD5F704240'' restored on Cave of Ardales', '[{"source": "https://es.wikipedia.org/wiki/Cueva_de_Ardales", "url": "https://es.wikipedia.org/wiki/Cueva_de_Ardales", "quote": "36.87280170888, -4.8288339138279", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=23320", "url": "https://www.megalithic.co.uk/article.php?sid=23320", "quote": "Latitude: 36.872794N Longitude: 4.82885W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0130)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Spanish Wikipedia article on the cave and the Megalithic Portal both put the cave entrance on the Cerro de la Calinoria at c. 36.8728, -4.8288 (OpenStreetMap''s cave-entrance node agrees); the stored point is the centre of Ardales town, about 1.5 km away, so it is replaced.", "value_page": null}]'::jsonb),
    ('010c0b09-760b-44f6-ba68-1f0353c7b3e6'::uuid, 'lat', '36.872802', '36.877923669201024', 'fields-wd1-2026-09-26b-s001-rollback:010c0b09-760b-44f6-ba68-1f0353c7b3e6:lat', 'rollback of fields-wd1-2026-09-26b-s001: lat ''36.877923669201024'' restored on Cave of Ardales', '[{"source": "https://es.wikipedia.org/wiki/Cueva_de_Ardales", "url": "https://es.wikipedia.org/wiki/Cueva_de_Ardales", "quote": "36.87280170888, -4.8288339138279", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=23320", "url": "https://www.megalithic.co.uk/article.php?sid=23320", "quote": "Latitude: 36.872794N Longitude: 4.82885W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0130)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Spanish Wikipedia article on the cave and the Megalithic Portal both put the cave entrance on the Cerro de la Calinoria at c. 36.8728, -4.8288 (OpenStreetMap''s cave-entrance node agrees); the stored point is the centre of Ardales town, about 1.5 km away, so it is replaced.", "value_page": null}]'::jsonb),
    ('010c0b09-760b-44f6-ba68-1f0353c7b3e6'::uuid, 'lon', '-4.828834', '-4.844690017051738', 'fields-wd1-2026-09-26b-s001-rollback:010c0b09-760b-44f6-ba68-1f0353c7b3e6:lon', 'rollback of fields-wd1-2026-09-26b-s001: lon ''-4.844690017051738'' restored on Cave of Ardales', '[{"source": "https://es.wikipedia.org/wiki/Cueva_de_Ardales", "url": "https://es.wikipedia.org/wiki/Cueva_de_Ardales", "quote": "36.87280170888, -4.8288339138279", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=23320", "url": "https://www.megalithic.co.uk/article.php?sid=23320", "quote": "Latitude: 36.872794N Longitude: 4.82885W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0130)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Spanish Wikipedia article on the cave and the Megalithic Portal both put the cave entrance on the Cerro de la Calinoria at c. 36.8728, -4.8288 (OpenStreetMap''s cave-entrance node agrees); the stored point is the centre of Ardales town, about 1.5 km away, so it is replaced.", "value_page": null}]'::jsonb),
    ('010c0b09-760b-44f6-ba68-1f0353c7b3e6'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s001-rollback:010c0b09-760b-44f6-ba68-1f0353c7b3e6:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1 - 500 AD'' restored on Cave of Ardales', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('010c0b09-760b-44f6-ba68-1f0353c7b3e6'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s001-rollback:010c0b09-760b-44f6-ba68-1f0353c7b3e6:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1'' restored on Cave of Ardales', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0130)", "decision": "clear", "status": "MISSING", "reasoning": "The cave''s use begins in the Palaeolithic (pigments dated to over 64,800-65,000 years ago, disputed; Upper Palaeolithic art c. 30,000 years old), so the stored AD 1 is wrong; but every source found states these dates only as ''years ago'', which cannot be read as a year, so no two sources give a readable start and the field is emptied.", "value_page": null}]'::jsonb),
    ('010c0b09-760b-44f6-ba68-1f0353c7b3e6'::uuid, 'source_url', 'https://es.wikipedia.org/wiki/Cueva_de_Ardales', 'https://en.wikipedia.org/wiki/Ardales', 'fields-wd1-2026-09-26b-s001-rollback:010c0b09-760b-44f6-ba68-1f0353c7b3e6:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Ardales'' restored on Cave of Ardales', '[{"source": "https://es.wikipedia.org/wiki/Cueva_de_Ardales", "url": "https://es.wikipedia.org/wiki/Cueva_de_Ardales", "quote": "La cueva de Ardales, también conocida como cueva de doña Trinidad Grund, es una cueva situada en el municipio andaluz de Ardales (Málaga, España). Es un yacimiento prehistórico con arte parietal del Paleolítico.", "outcome": "found"}, {"source": "https://www.showcaves.com/english/es/showcaves/Ardales.html", "url": "https://www.showcaves.com/english/es/showcaves/Ardales.html", "quote": "The Cueva de Ardales near the town Ardales is a karst cave with cave paintings.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0130)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the municipality of Ardales (English ''Cave of Ardales'' redirects there); the cave has its own article only in Spanish Wikipedia, which is about this very site, and Showcaves names the same cave near Ardales.", "value_page": {"lang": "es", "problem": null, "resolved_title": "Cueva de Ardales", "unreadable": false, "wikibase_item": "Q5401214"}}]'::jsonb),
    ('019d61e6-08f4-46d8-bb15-78141831d5cf'::uuid, 'site_type', 'Settlement', 'Museum', 'fields-wd1-2026-09-26b-s001-rollback:019d61e6-08f4-46d8-bb15-78141831d5cf:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Museum'' restored on Gene fornby', '[{"source": "https://exarc.net/issue-2013-1/aoam/gene-fornby-ancient-village-gene", "url": "https://exarc.net/issue-2013-1/aoam/gene-fornby-ancient-village-gene", "quote": "Gene Fornby is a reconstructed settlement based on a prehistoric settlement on Genesmon in Gene (parish of Själevad), outside the city of Örnsköldsvik in northern Sweden.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Gene_fornby", "url": "https://en.wikipedia.org/wiki/Gene_fornby", "quote": "the settlement itself dated back to the Roman Iron Age", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0136)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ancient site is the excavated Roman Iron Age farm settlement on Genesmon with its burial mounds; the museum is only the modern reconstruction beside it. Both EXARC and Wikipedia describe the site as a settlement, so ''Museum'' is replaced by ''Settlement''.", "value_page": null}]'::jsonb),
    ('021307e1-d101-463b-a4ec-0c6cfbad0b7e'::uuid, 'site_type', 'Tomb', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s001-rollback:021307e1-d101-463b-a4ec-0c6cfbad0b7e:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Necropolis/tombs complex'' restored on Tombeau de Tin Hinan', '[{"source": "https://en.wikipedia.org/wiki/Tin_Hinan_Tomb", "url": "https://en.wikipedia.org/wiki/Tin_Hinan_Tomb", "quote": "is a monumental tomb located at Abalessa in the Sahara", "outcome": "found"}, {"source": "https://revistas.uam.es/cupauam/article/view/6990", "url": "https://revistas.uam.es/cupauam/article/view/6990", "quote": "The discovery of the tomb of a person of rank in the Algerian Sahara in the year 1925", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a single monumental tomb (the Abalessa monument with the burial attributed to Tin Hinan), not a necropolis complex; Wikipedia and García Sánchez (CuPAUAM 42) both describe it as a tomb.", "value_page": null}]'::jsonb),
    ('021307e1-d101-463b-a4ec-0c6cfbad0b7e'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Tin_Hinan_Tomb', 'https://en.wikipedia.org/wiki/Tin_Hinan', 'fields-wd1-2026-09-26b-s001-rollback:021307e1-d101-463b-a4ec-0c6cfbad0b7e:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Tin_Hinan'' restored on Tombeau de Tin Hinan', '[{"source": "https://en.wikipedia.org/wiki/Tin_Hinan_Tomb", "url": "https://en.wikipedia.org/wiki/Tin_Hinan_Tomb", "quote": "In the 1960s, the anthropologist E. Leblanc examined the skeleton within the Tin Hinan tomb.", "outcome": "found"}, {"source": "https://revistas.uam.es/cupauam/article/view/6990", "url": "https://revistas.uam.es/cupauam/article/view/6990", "quote": "Tin Hinan tomb revisited: new sources relating to the Byron Khun de Prorok’s excavation in Abalessa (Ahaggar, Algeria)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the woman Tin Hinan; English Wikipedia has a dedicated article on the tomb at Abalessa (Tin Hinan Tomb), which the CuPAUAM article independently names.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Tin Hinan Tomb", "unreadable": false, "wikibase_item": "Q3531165"}}]'::jsonb),
    ('021e7e01-8d62-4480-ae4a-454bc7d78b7f'::uuid, 'geom', 'SRID=4326;POINT(8.833528 47.217011)', '0101000020E61000005C5272E1AEAA2140FFE71FAFE19D4740', 'fields-wd1-2026-09-26b-s001-rollback:021e7e01-8d62-4480-ae4a-454bc7d78b7f:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E61000005C5272E1AEAA2140FFE71FAFE19D4740'' restored on Busskirch', '[{"source": "https://www.wikidata.org/wiki/Q11722170", "url": "https://www.wikidata.org/wiki/Q11722170", "quote": "47°13''1\"N, 8°50''2\"E", "outcome": "found"}, {"source": "https://imperium.ahlfeldt.se/places/38863", "url": "https://imperium.ahlfeldt.se/places/38863", "quote": "47.21704, 8.83348", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0138)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Roman remains lie beneath the church of St. Martin on the Busskirch peninsula; Wikidata''s item for that church places it at 47°13''1\"N 8°50''2\"E and the Digital Atlas of the Roman Empire puts the ancient place Busskirch at 47.21704, 8.83348. The stored point (the village''s minute-precision coordinate) lies about 1.8 km north of it, so it is replaced.", "value_page": null}]'::jsonb),
