    ('021e7e01-8d62-4480-ae4a-454bc7d78b7f'::uuid, 'lon', '8.833528', '8.833365483479774', 'fields-wd1-2026-09-26b-s001-rollback:021e7e01-8d62-4480-ae4a-454bc7d78b7f:lon', 'rollback of fields-wd1-2026-09-26b-s001: lon ''8.833365483479774'' restored on Busskirch', '[{"source": "https://www.wikidata.org/wiki/Q11722170", "url": "https://www.wikidata.org/wiki/Q11722170", "quote": "47°13''1\"N, 8°50''2\"E", "outcome": "found"}, {"source": "https://imperium.ahlfeldt.se/places/38863", "url": "https://imperium.ahlfeldt.se/places/38863", "quote": "47.21704, 8.83348", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0138)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Roman remains lie beneath the church of St. Martin on the Busskirch peninsula; Wikidata''s item for that church places it at 47°13''1\"N 8°50''2\"E and the Digital Atlas of the Roman Empire puts the ancient place Busskirch at 47.21704, 8.83348. The stored point (the village''s minute-precision coordinate) lies about 1.8 km north of it, so it is replaced.", "value_page": null}]'::jsonb),
    ('0255f640-58e0-4f86-b5e7-620bae889794'::uuid, 'site_type', 'City', 'Temple complex', 'fields-wd1-2026-09-26b-s001-rollback:0255f640-58e0-4f86-b5e7-620bae889794:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Temple complex'' restored on Elaiussa Sebaste', '[{"source": "https://topostext.org/place/365342UEla", "url": "https://topostext.org/place/365342UEla", "quote": "Ἐλαιοῦσσα - Elaioussa Sebaste, Roman island city of Cilicia", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Elaiussa_Sebaste", "url": "https://en.wikipedia.org/wiki/Elaiussa_Sebaste", "quote": "The city entered a golden age when the Roman Emperor", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0143)", "decision": "replace", "status": "CONFLICT", "reasoning": "Elaiussa Sebaste is an ancient city with theatre, agora, baths, churches, necropolis and a single temple outside the town; ToposText calls it a Roman island city and Wikipedia treats it as a city, so City replaces Temple complex.", "value_page": null}]'::jsonb),
    ('0286a741-77f2-4148-8e62-487041920281'::uuid, 'period_name', NULL, '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s001-rollback:0286a741-77f2-4148-8e62-487041920281:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1000 - 1500 AD'' restored on Cochapata', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0286a741-77f2-4148-8e62-487041920281'::uuid, 'period_start', NULL, '1400', 'fields-wd1-2026-09-26b-s001-rollback:0286a741-77f2-4148-8e62-487041920281:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1400'' restored on Cochapata', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0107)", "decision": "clear", "status": "MISSING", "reasoning": "The sources on Cochapata (Wikipedia, the MINCETUR inventory) say only that it was an Inca construction and give no year or century for its building or first occupation; no two sources date the start.", "value_page": null}]'::jsonb),
    ('0286a741-77f2-4148-8e62-487041920281'::uuid, 'site_type', NULL, 'City/town/settlement', 'fields-wd1-2026-09-26b-s001-rollback:0286a741-77f2-4148-8e62-487041920281:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''City/town/settlement'' restored on Cochapata', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0107)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia calls Cochapata only an archaeological site; the MINCETUR inventory entry calls it an Inca archaeological complex but its description mixes in text about the homonymous Qochapata near Sacsayhuaman in Cusco, so no two independent sources reliably say what kind of site this Cochapata is.", "value_page": null}]'::jsonb),
    ('033b359c-dc2e-4fea-a61e-cd2ad0ca9bbe'::uuid, 'period_name', '1 - 500 AD', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s001-rollback:033b359c-dc2e-4fea-a61e-cd2ad0ca9bbe:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 BC - 1 AD'' restored on Belgrade Fortress', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('033b359c-dc2e-4fea-a61e-cd2ad0ca9bbe'::uuid, 'period_start', '1', '-500', 'fields-wd1-2026-09-26b-s001-rollback:033b359c-dc2e-4fea-a61e-cd2ad0ca9bbe:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-500'' restored on Belgrade Fortress', '[{"source": "https://www.beogradskatvrdjava.co.rs/o-kompleksu/?lang=en", "url": "https://www.beogradskatvrdjava.co.rs/o-kompleksu/?lang=en", "quote": "At the beginning of the 1st century CE, most probably between 6 and 11 CE, increasingly frequent attacks by barbarian tribes on the ridge near the confluence of the Sava and the Danube led to the establishment of the first Roman military camp.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Belgrade_Fortress", "url": "https://en.wikipedia.org/wiki/Belgrade_Fortress", "quote": "The original military camp was probably occupied by the soldiers from the Legio VIII Augusta from 46 AD to 69.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Belgrade_Fortress", "url": "https://en.wikipedia.org/wiki/Belgrade_Fortress", "quote": "The presence of Legio IV prompted the construction of a square-shaped castrum (fort), which occupied Upper Town of today''s fortress. Construction began at the turn of the 2nd century AD as since the early 100s, Legio IV Flavia Felix became permanently stationed in Singidunum.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0125)", "decision": "replace", "status": "CONFLICT", "reasoning": "The fortress''s operator (JP Beogradska tvrđava) states that the Celtic Singidunum of the 3rd century BC lay at Karaburma, not in the fortress, and dates the first Roman military camp on the ridge to the beginning of the 1st century CE; Wikipedia has the first camp occupied from 46 AD and the stone castrum built at the turn of the 2nd century AD. The fortress''s history therefore starts in the 1st century AD, in the 1-500 AD bucket, not in 500 BC - 1 AD.", "value_page": null}]'::jsonb),
    ('0371ed0a-82f5-4578-b7bf-10dc40faf580'::uuid, 'site_type', 'Temple complex', 'Megalithic structures', 'fields-wd1-2026-09-26b-s001-rollback:0371ed0a-82f5-4578-b7bf-10dc40faf580:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Megalithic structures'' restored on Baalbek', '[{"source": "https://en.wikipedia.org/wiki/Baalbek", "url": "https://en.wikipedia.org/wiki/Baalbek", "quote": "The Roman temple complex grew up from the early part of the reign of Augustus in the late 1st century BC until the rise of Christianity in the 4th century", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=14821", "url": "https://www.megalithic.co.uk/article.php?sid=14821", "quote": "Site Name: Baalbek Temple Alternative Name: Heliopolis Country: Lebanon Type: Ancient Temple", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Tempel_von_Baalbek", "url": "https://de.wikipedia.org/wiki/Tempel_von_Baalbek", "quote": "Zu den Tempelanlagen gehören das gewaltige Jupiterheiligtum, der außergewöhnlich gut erhaltene Bacchustempel und der Rundtempel mit seiner einmaligen Formgebung.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0092)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe the site as a Roman temple complex (Jupiter sanctuary, Temple of Bacchus, round temple); its megalithic blocks are part of the Temple of Jupiter''s podium, so Temple complex is the most specific type that holds.", "value_page": null}]'::jsonb),
    ('0371ed0a-82f5-4578-b7bf-10dc40faf580'::uuid, 'source_url', 'https://de.wikipedia.org/wiki/Tempel_von_Baalbek', 'https://en.wikipedia.org/wiki/Baalbek', 'fields-wd1-2026-09-26b-s001-rollback:0371ed0a-82f5-4578-b7bf-10dc40faf580:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Baalbek'' restored on Baalbek', '[{"source": "https://de.wikipedia.org/wiki/Tempel_von_Baalbek", "url": "https://de.wikipedia.org/wiki/Tempel_von_Baalbek", "quote": "Die Tempelanlagen von Baalbek enthalten einige der größten und am besten erhaltenen Beispiele für kaiserzeitliche römische Architektur im Nahen Osten", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=14821", "url": "https://www.megalithic.co.uk/article.php?sid=14821", "quote": "Site Name: Baalbek Temple Alternative Name: Heliopolis Country: Lebanon", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0092)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the modern city; the German article Tempel von Baalbek (Wikidata Q14524645, temples of Baalbek) is about the temple complex itself, which the Megalithic Portal also records as Baalbek Temple.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Tempel von Baalbek", "unreadable": false, "wikibase_item": "Q14524645"}}]'::jsonb),
    ('037e3715-f5f7-4345-8216-8aa26f404009'::uuid, 'geom', 'SRID=4326;POINT(-7.869349 54.506088)', '0101000020E6100000D84045B34F551FC08A41436B26424B40', 'fields-wd1-2026-09-26b-s001-rollback:037e3715-f5f7-4345-8216-8aa26f404009:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E6100000D84045B34F551FC08A41436B26424B40'' restored on Boa Island', '[{"source": "https://www.megalithic.co.uk/article.php?sid=23656", "url": "https://www.megalithic.co.uk/article.php?sid=23656", "quote": "Latitude: 54.506088N Longitude: 7.869349W", "outcome": "found"}, {"source": "https://www.tuatha.ie/boa-island/", "url": "https://www.tuatha.ie/boa-island/", "quote": "Lat. 54.5064, Long. -7.8698", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0101)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the pair of carved stone figures in Caldragh graveyard at the west end of Boa Island. The Megalithic Portal and Tuatha both put them at about 54.506, -7.869, about 2.6 km from the stored point, which is the island''s centroid.", "value_page": null}]'::jsonb),
