    ('037e3715-f5f7-4345-8216-8aa26f404009'::uuid, 'period_name', '1 - 500 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s001-rollback:037e3715-f5f7-4345-8216-8aa26f404009:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1500 - 500 BC'' restored on Boa Island', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('037e3715-f5f7-4345-8216-8aa26f404009'::uuid, 'period_start', '1', '-1000', 'fields-wd1-2026-09-26b-s001-rollback:037e3715-f5f7-4345-8216-8aa26f404009:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-1000'' restored on Boa Island', '[{"source": "https://en.wikipedia.org/wiki/Boa_Island_figures", "url": "https://en.wikipedia.org/wiki/Boa_Island_figures", "quote": "1st century AD", "outcome": "found"}, {"source": "https://daysoutni.com/boa-island-caldragh-figures/", "url": "https://daysoutni.com/boa-island-caldragh-figures/", "quote": "Scholars commonly date it to around the first century AD, which would make it some two thousand years old.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0101)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia''s article on the figures (created Iron Age, 1st century AD) and Days Out NI both date the Janus figure to around the 1st century AD; the rival early-Christian reading still falls in the same bucket, since Caldragh graveyard dates from 400-800 AD. So the stored -1000 (Bronze Age) is replaced with 1.", "value_page": null}]'::jsonb),
    ('037e3715-f5f7-4345-8216-8aa26f404009'::uuid, 'site_type', 'Sculptured stone', 'Rock relief/carving', 'fields-wd1-2026-09-26b-s001-rollback:037e3715-f5f7-4345-8216-8aa26f404009:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Rock relief/carving'' restored on Boa Island', '[{"source": "https://www.megalithic.co.uk/article.php?sid=23656", "url": "https://www.megalithic.co.uk/article.php?sid=23656", "quote": "Sculptured Stone", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Boa_Island_figures", "url": "https://en.wikipedia.org/wiki/Boa_Island_figures", "quote": "The Boa Island figures are two stone idols in the Caldragh graveyard on Boa Island", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0101)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is two free-standing carved stone idols (the Janus/Dreenan figure and the Lustymore figure), which the Megalithic Portal classes as a sculptured stone; they are statues, not a relief carved into living rock, so Sculptured stone fits better than Rock relief/carving.", "value_page": null}]'::jsonb),
    ('037e3715-f5f7-4345-8216-8aa26f404009'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Boa_Island_figures', 'https://en.wikipedia.org/wiki/Boa_Island', 'fields-wd1-2026-09-26b-s001-rollback:037e3715-f5f7-4345-8216-8aa26f404009:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Boa_Island'' restored on Boa Island', '[{"source": "https://en.wikipedia.org/wiki/Boa_Island_figures", "url": "https://en.wikipedia.org/wiki/Boa_Island_figures", "quote": "The Boa Island figures are two stone idols in the Caldragh graveyard on Boa Island", "outcome": "found"}, {"source": "https://www.fermanaghlakelands.com/things-to-see-and-do/janus-figure-boa-island-p700781", "url": "https://www.fermanaghlakelands.com/things-to-see-and-do/janus-figure-boa-island-p700781", "quote": "This very well-known stone figure has been sitting in the rural graveyard at Caldragh, in Dreenan, on Boa Island since at least 1841.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0101)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored page is about the whole island; English Wikipedia has its own article on the Boa Island figures, the monument itself, which Fermanagh Lakelands describes too.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Boa Island figures", "unreadable": false, "wikibase_item": "Q135489651"}}]'::jsonb),
    ('03a7a357-12a8-40f9-ae6a-9cef78135fd3'::uuid, 'period_name', '1 - 500 AD', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s001-rollback:03a7a357-12a8-40f9-ae6a-9cef78135fd3:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 BC - 1 AD'' restored on Dubris', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(43) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('03a7a357-12a8-40f9-ae6a-9cef78135fd3'::uuid, 'period_start', '43', '-500', 'fields-wd1-2026-09-26b-s001-rollback:03a7a357-12a8-40f9-ae6a-9cef78135fd3:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-500'' restored on Dubris', '[{"source": "https://heritage.kent.gov.uk/Monument/MKE7075", "url": "https://heritage.kent.gov.uk/Monument/MKE7075", "quote": "SETTLEMENT (SETTLEMENT, Roman - 43 AD to 409 AD)", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Dubris", "url": "https://en.wikipedia.org/wiki/Dubris", "quote": "though the general consensus is for a 1st-century AD date", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0033)", "decision": "replace", "status": "MISSING", "reasoning": "The Kent HER record for the Roman town and port of Dubris dates the settlement from the Roman conquest, 43 AD, to 409 AD. Wikipedia dates the port''s first structures, its two lighthouses, to the 1st century AD, soon after the conquest. Caesar''s 55 BC approach to the harbour is not a settlement, so the start belongs in the 1 - 500 AD bucket, not the stored 500 BC - 1 AD one.", "value_page": null}]'::jsonb),
