    ('03c54b35-5554-497f-b91e-a2a77f3325e1'::uuid, 'period_start', '-600', '-3000', 'fields-wd1-2026-09-26b-s001-rollback:03c54b35-5554-497f-b91e-a2a77f3325e1:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-3000'' restored on Acropolis of Alatri', '[{"source": "https://web.astronomicalheritage.net/index.php/show-entity?identity=27&idsubentity=1", "url": "https://web.astronomicalheritage.net/index.php/show-entity?identity=27&idsubentity=1", "quote": "the substructure of an archaic building (6th-5th century BC), possibly a temple, has been unearthed", "outcome": "found"}, {"source": "https://megalithicminutiae.com/alatri/", "url": "https://megalithicminutiae.com/alatri/", "quote": "Dating: 6th-3rd centuries BC", "outcome": "found"}, {"source": "https://it.wikipedia.org/wiki/Acropoli_di_Alatri", "url": "https://it.wikipedia.org/wiki/Acropoli_di_Alatri", "quote": "alcuni studiosi le collocano al VI secolo a.C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0084)", "decision": "replace", "status": "MISSING", "reasoning": "The earliest datable structure on the acropolis is an archaic building of the 6th-5th century BC (Magli, UNESCO astronomical-heritage portal), and the site is dated from the 6th century BC (Megalithic Minutiae; some scholars cited by Wikipedia); the stored 3000 BC has no support, so the start becomes -600.", "value_page": null}]'::jsonb),
    ('03c54b35-5554-497f-b91e-a2a77f3325e1'::uuid, 'source_url', 'https://it.wikipedia.org/wiki/Acropoli_di_Alatri', 'https://www3.astronomicalheritage.net/index.php/show-entity?identity=27&idsubentity=1', 'fields-wd1-2026-09-26b-s001-rollback:03c54b35-5554-497f-b91e-a2a77f3325e1:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://www3.astronomicalheritage.net/index.php/show-entity?identity=27&idsubentity=1'' restored on Acropolis of Alatri', '[{"source": "https://it.wikipedia.org/wiki/Acropoli_di_Alatri", "url": "https://it.wikipedia.org/wiki/Acropoli_di_Alatri", "quote": "Acropoli di Alatri. La Porta Maggiore", "outcome": "found"}, {"source": "https://www.theancientconnection.com/megaliths/italy/megalithic-alatri/", "url": "https://www.theancientconnection.com/megaliths/italy/megalithic-alatri/", "quote": "The Acropolis of Alatri, at the heart of the historical center of the eponymous city, is located on top of the hill where the city is located.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0084)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL redirects from www3 to another host; the site has its own Wikipedia article (Italian, no English one), which loads as plain HTML and is about this acropolis, so it becomes the source.", "value_page": {"lang": "it", "problem": null, "resolved_title": "Acropoli di Alatri", "unreadable": false, "wikibase_item": "Q3604769"}}]'::jsonb),
    ('03fdf67f-1fcc-49ae-b6c8-ed3aff640d30'::uuid, 'source_url', 'https://uk.wikipedia.org/wiki/%D0%A1%D1%83%D1%88%D0%BA%D1%96%D0%B2%D1%81%D1%8C%D0%BA%D0%B5_%D0%BF%D0%BE%D1%81%D0%B5%D0%BB%D0%B5%D0%BD%D0%BD%D1%8F', 'https://en.wikipedia.org/wiki/Sushkivka', 'fields-wd1-2026-09-26b-s001-rollback:03fdf67f-1fcc-49ae-b6c8-ed3aff640d30:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Sushkivka'' restored on Sushkivka', '[{"source": "https://uk.wikipedia.org/wiki/%D0%A1%D1%83%D1%88%D0%BA%D1%96%D0%B2%D1%81%D1%8C%D0%BA%D0%B5_%D0%BF%D0%BE%D1%81%D0%B5%D0%BB%D0%B5%D0%BD%D0%BD%D1%8F", "url": "https://uk.wikipedia.org/wiki/%D0%A1%D1%83%D1%88%D0%BA%D1%96%D0%B2%D1%81%D1%8C%D0%BA%D0%B5_%D0%BF%D0%BE%D1%81%D0%B5%D0%BB%D0%B5%D0%BD%D0%BD%D1%8F", "quote": "Сушківське поселення — поселення трипільської культури", "outcome": "found"}, {"source": "https://www.sfb1266.uni-kiel.de/en/projects/cluster-c/d1-population-agglomerations-at-tripolye-cucuteni-mega-sites/trypillia-megasites/mega-structures-and-dwellings", "url": "https://www.sfb1266.uni-kiel.de/en/projects/cluster-c/d1-population-agglomerations-at-tripolye-cucuteni-mega-sites/trypillia-megasites/mega-structures-and-dwellings", "quote": "such as the one from Sushkivka (Uman district, Cherkassy oblast), excavated in 1916 by V. Ye. Kozlovska", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0152)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English article ''Sushkivka'' does not exist (the village is covered elsewhere); the Ukrainian Wikipedia article ''Сушківське поселення'' is about the Trypillia settlement itself, found in 1916 and 1926 near the village in Uman district, and the Kiel CRC 1266 project page independently names the Sushkivka house model excavated in 1916 by Kozlovska.", "value_page": {"lang": "uk", "problem": null, "resolved_title": "Сушківське поселення", "unreadable": false, "wikibase_item": "Q12159022"}}]'::jsonb),
    ('0415d29e-5239-40c6-ab1d-5b19e443336b'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s001-rollback:0415d29e-5239-40c6-ab1d-5b19e443336b:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''4500 - 3000 BC'' restored on Odigitria', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0415d29e-5239-40c6-ab1d-5b19e443336b'::uuid, 'period_start', '-3000', '-4000', 'fields-wd1-2026-09-26b-s001-rollback:0415d29e-5239-40c6-ab1d-5b19e443336b:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-4000'' restored on Odigitria', '[{"source": "https://lithoscrete.com/crete/odigitria-prepalatial-cemetery/", "url": "https://lithoscrete.com/crete/odigitria-prepalatial-cemetery/", "quote": "Although the Odigitria Prepalatial Cemetery existed long before fancy palaces were built, it remained an important burial spot for Minoan people for about 1,000 years, from around 3000 to 2000 BC.", "outcome": "found"}, {"source": "https://www.cretanbeaches.com/en/history-of-crete/archaeological-sites-in-crete/minoan-times-palaces-and-sites/odigitria-prepalatial-cemetery", "url": "https://www.cretanbeaches.com/en/history-of-crete/archaeological-sites-in-crete/minoan-times-palaces-and-sites/odigitria-prepalatial-cemetery", "quote": "Peak Period: Minoan Era (3000 BC-1200 BC)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0069)", "decision": "replace", "status": "MISSING", "reasoning": "The cemetery''s first tholos was built at the beginning of Early Minoan I (Wikipedia, minoancrete.com); Lithoscrete dates its use from around 3000 BC and Cretan Beaches places it in the Minoan era from 3000 BC, early in that era, so the start is c. 3000 BC, not the Final Neolithic -4000.", "value_page": null}]'::jsonb),
    ('041bcb70-5676-4ef5-bab2-07f2153098c0'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s001-rollback:041bcb70-5676-4ef5-bab2-07f2153098c0:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''3000 - 1500 BC'' restored on Menelaion', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1450) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('041bcb70-5676-4ef5-bab2-07f2153098c0'::uuid, 'period_start', '-1450', '-3000', 'fields-wd1-2026-09-26b-s001-rollback:041bcb70-5676-4ef5-bab2-07f2153098c0:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-3000'' restored on Menelaion', '[{"source": "https://en.wikipedia.org/wiki/Menelaion", "url": "https://en.wikipedia.org/wiki/Menelaion", "quote": "Mansion 1 - Original building facing south assembling three parallel units. The central unit is considered a megaron. It was built about 1450 BCE and soon destroyed by possible earthquake.", "outcome": "found"}, {"source": "https://golden-greece.gr/en/archaeological/peloponisos/lakonia/arxaio-menelaion-lakonia", "url": "https://golden-greece.gr/en/archaeological/peloponisos/lakonia/arxaio-menelaion-lakonia", "quote": "while the construction on the hill of Menelaion itself of a mega-shaped building - after the middle of the 15th century BC. (Late Helladic IIB)- which probably served as an administrative center", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0068)", "decision": "replace", "status": "MISSING", "reasoning": "The first dated building on the Menelaion hill is the Mycenaean Mansion 1, built about 1450 BCE (Wikipedia, after Catling) - after the middle of the 15th century BC (golden-greece, following the Greek Ministry of Culture); the hero shrine followed in the 8th century BC. The start therefore lies in 1500 - 500 BC, not in the stored bucket 3000 - 1500 BC; the Middle Helladic finds belong to the neighbouring North hill and carry no dated year.", "value_page": null}]'::jsonb),
    ('041bcb70-5676-4ef5-bab2-07f2153098c0'::uuid, 'site_type', 'Sanctuary', 'City/town/settlement', 'fields-wd1-2026-09-26b-s001-rollback:041bcb70-5676-4ef5-bab2-07f2153098c0:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''City/town/settlement'' restored on Menelaion', '[{"source": "https://realsparta.gr/en-us/what-to-do/archaelogical-sites-monuments/menelaion", "url": "https://realsparta.gr/en-us/what-to-do/archaelogical-sites-monuments/menelaion", "quote": "Near Sparta, at the top of the hill of Prophet Elias that dominates the eastern side of Evrotas, are the ruins of a sanctuary built in honor of the deified Menelaus and Helen.", "outcome": "found"}, {"source": "https://madainproject.com/archaeological_site_of_menelaion", "url": "https://madainproject.com/archaeological_site_of_menelaion", "quote": "The Archaeological Site of Menelaion, also known as Therapne, is an ancient sanctuary located near ancient Sparta in Laconia, Greece.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Menelaion", "url": "https://en.wikipedia.org/wiki/Menelaion", "quote": "the new sanctuary was built upon the ancient edifice", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0068)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Menelaion is the hero shrine (heroon) of Menelaus and Helen at Therapne, described as a sanctuary by the Sparta tourism site, the Madain Project and Wikipedia; the Mycenaean mansions beneath it are a few buildings, not a town, so Sanctuary replaces City/town/settlement.", "value_page": null}]'::jsonb),
    ('045e2515-7952-4245-9cc3-e335f0341484'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s001-rollback:045e2515-7952-4245-9cc3-e335f0341484:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''3000 - 1500 BC'' restored on Bonstorf Barrows', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1500) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('045e2515-7952-4245-9cc3-e335f0341484'::uuid, 'period_start', '-1500', '-3000', 'fields-wd1-2026-09-26b-s001-rollback:045e2515-7952-4245-9cc3-e335f0341484:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-3000'' restored on Bonstorf Barrows', '[{"source": "https://en.wikipedia.org/wiki/Bonstorf_Barrows", "url": "https://en.wikipedia.org/wiki/Bonstorf_Barrows", "quote": "The grave finds are characteristic of the old Bronze Age (i.e. from about 1500 to 1200 BC) in the Lüneburg Heath", "outcome": "found"}, {"source": "https://www.region-celle-navigator.de/inhaltsverzeichnis/details/poi-314595-3090-Grabhuegelfeld_von_Bonstorf.html", "url": "https://www.region-celle-navigator.de/inhaltsverzeichnis/details/poi-314595-3090-Grabhuegelfeld_von_Bonstorf.html", "quote": "Die bronzenen Beigaben sind bezeichnend für die ältere Bronzezeit in der Lüneburger Heide (ca. 1500 – 1200 v. Chr.)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "replace", "status": "MISSING", "reasoning": "The only dated evidence is the barrow excavated in 1973, whose bronze grave goods Wikipedia and the Landkreis Celle information text both place in the Older Bronze Age, c. 1500-1200 BC; the Lower Saxony heritage register also dates the barrow field to the Older Bronze Age. The ''late Neolithic'' start both sources mention as an alternative carries no date, so the attested start is c. 1500 BC, not the stored 3000 BC.", "value_page": null}]'::jsonb),
    ('046ccbd9-e5a6-4050-9dfb-83c578344fc1'::uuid, 'geom', 'SRID=4326;POINT(14.266013 41.228301)', '0101000020E61000007139E3C7FB7F2C400AC7FC9F9E994440', 'fields-wd1-2026-09-26b-s001-rollback:046ccbd9-e5a6-4050-9dfb-83c578344fc1:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E61000007139E3C7FB7F2C400AC7FC9F9E994440'' restored on Trebula Balliensis', '[{"source": "https://en.wikipedia.org/wiki/Trebula_Balliensis", "url": "https://en.wikipedia.org/wiki/Trebula_Balliensis", "quote": "41°13′42″N 14°15′58″E", "outcome": "found"}, {"source": "https://topostext.org/place/412143UTre", "url": "https://topostext.org/place/412143UTre", "quote": "Latitude: 41.227100 Longitude: 14.261700", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0089)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ancient city lies northeast of modern Treglia (acropolis on colle Monticelli, town on the La Corte plateau); English Wikipedia and ToposText (Trebula, Campania, modern Treglia) agree within 0.4 km, while the stored point is a coarse 1-arcminute point 3.4 km to the south.", "value_page": null}]'::jsonb),
    ('046ccbd9-e5a6-4050-9dfb-83c578344fc1'::uuid, 'lat', '41.228301', '41.20015334932948', 'fields-wd1-2026-09-26b-s001-rollback:046ccbd9-e5a6-4050-9dfb-83c578344fc1:lat', 'rollback of fields-wd1-2026-09-26b-s001: lat ''41.20015334932948'' restored on Trebula Balliensis', '[{"source": "https://en.wikipedia.org/wiki/Trebula_Balliensis", "url": "https://en.wikipedia.org/wiki/Trebula_Balliensis", "quote": "41°13′42″N 14°15′58″E", "outcome": "found"}, {"source": "https://topostext.org/place/412143UTre", "url": "https://topostext.org/place/412143UTre", "quote": "Latitude: 41.227100 Longitude: 14.261700", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0089)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ancient city lies northeast of modern Treglia (acropolis on colle Monticelli, town on the La Corte plateau); English Wikipedia and ToposText (Trebula, Campania, modern Treglia) agree within 0.4 km, while the stored point is a coarse 1-arcminute point 3.4 km to the south.", "value_page": null}]'::jsonb),
    ('046ccbd9-e5a6-4050-9dfb-83c578344fc1'::uuid, 'lon', '14.266013', '14.249967810141898', 'fields-wd1-2026-09-26b-s001-rollback:046ccbd9-e5a6-4050-9dfb-83c578344fc1:lon', 'rollback of fields-wd1-2026-09-26b-s001: lon ''14.249967810141898'' restored on Trebula Balliensis', '[{"source": "https://en.wikipedia.org/wiki/Trebula_Balliensis", "url": "https://en.wikipedia.org/wiki/Trebula_Balliensis", "quote": "41°13′42″N 14°15′58″E", "outcome": "found"}, {"source": "https://topostext.org/place/412143UTre", "url": "https://topostext.org/place/412143UTre", "quote": "Latitude: 41.227100 Longitude: 14.261700", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0089)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ancient city lies northeast of modern Treglia (acropolis on colle Monticelli, town on the La Corte plateau); English Wikipedia and ToposText (Trebula, Campania, modern Treglia) agree within 0.4 km, while the stored point is a coarse 1-arcminute point 3.4 km to the south.", "value_page": null}]'::jsonb),
    ('04982451-5603-41cb-957d-758925170c8e'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s001-rollback:04982451-5603-41cb-957d-758925170c8e:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1 - 500 AD'' restored on M''Daourouch', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-300) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('04982451-5603-41cb-957d-758925170c8e'::uuid, 'period_start', '-300', '1', 'fields-wd1-2026-09-26b-s001-rollback:04982451-5603-41cb-957d-758925170c8e:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1'' restored on M''Daourouch', '[{"source": "https://www.ebsco.com/research-starters/history/madaurus", "url": "https://www.ebsco.com/research-starters/history/madaurus", "quote": "Founded in the third century BC with a mixed Berber and Phoenician population, it belonged toward the end of the century to Syphax, chief of the Numidian tribe of the Masaesyli and then to King Masinissa (d. 148).", "outcome": "found"}, {"source": "https://journals.openedition.org/encyclopedieberbere/396", "url": "https://journals.openedition.org/encyclopedieberbere/396", "quote": "qu’elle faisait partie du royaume de Syphax dès la fin du IIIe siècle av. J.-C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "MISSING", "reasoning": "The Princeton Encyclopedia text on EBSCO dates the founding of Madauros to the 3rd century BC, and the Encyclopédie berbère has the town in Syphax''s kingdom by the end of the 3rd century BC; the Roman colony came later (Flavian), so the start is -300, not the stored 1-500 AD bucket.", "value_page": null}]'::jsonb),
    ('04982451-5603-41cb-957d-758925170c8e'::uuid, 'site_type', 'City', 'Megalithic stones', 'fields-wd1-2026-09-26b-s001-rollback:04982451-5603-41cb-957d-758925170c8e:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Megalithic stones'' restored on M''Daourouch', '[{"source": "https://en.wikipedia.org/wiki/Madauros", "url": "https://en.wikipedia.org/wiki/Madauros", "quote": "Madauros (Madaurus, Madaura) was a Roman-Berber city and a former diocese of the Catholic Church in the old state of Numidia, in present-day Algeria.", "outcome": "found"}, {"source": "https://archiqoo.com/locations/madauros.php", "url": "https://archiqoo.com/locations/madauros.php", "quote": "Madauros, also called Madaure, is an ancient Roman city located in Mdawrush municipality in Souk Ahras Province, Algeria.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site at M''Daourouch is the ancient city of Madauros (forum, theatre, baths, basilicas, Byzantine fort); no source describes megalithic stones there, so the type is City.", "value_page": null}]'::jsonb),
    ('04982451-5603-41cb-957d-758925170c8e'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Madauros', 'https://en.wikipedia.org/wiki/M%27Daourouch', 'fields-wd1-2026-09-26b-s001-rollback:04982451-5603-41cb-957d-758925170c8e:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/M%27Daourouch'' restored on M''Daourouch', '[{"source": "https://en.wikipedia.org/wiki/Madauros", "url": "https://en.wikipedia.org/wiki/Madauros", "quote": "The ruins of Madauros are close to the current city of M''Daourouch (Arabic: مداوروش) in present-day Algeria.", "outcome": "found"}, {"source": "https://journals.openedition.org/encyclopedieberbere/396", "url": "https://journals.openedition.org/encyclopedieberbere/396", "quote": "Le site de Madauros est situé près de la ville actuelle de Mdaourouch qui tire son nom du toponyme antique.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the modern commune; English Wikipedia has its own article on the ancient site Madauros, confirmed by the Encyclopédie berbère entry on the same ruins near Mdaourouch.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Madauros", "unreadable": false, "wikibase_item": "Q11936307"}}]'::jsonb),
    ('04c8399c-298d-41ab-bb53-f56beb9e45da'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s001-rollback:04c8399c-298d-41ab-bb53-f56beb9e45da:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1500 - 500 BC'' restored on Gaer, Black Mountains', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('04c8399c-298d-41ab-bb53-f56beb9e45da'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s001-rollback:04c8399c-298d-41ab-bb53-f56beb9e45da:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-1500'' restored on Gaer, Black Mountains', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0154)", "decision": "clear", "status": "MISSING", "reasoning": "Cadw and Coflein only give the generic Iron Age (Cadw: c. 800 BC - AD 74) for Twyn-y-Gaer, while the one specific excavation-based date found (the Guardian obituary of the excavator Allan Probert: ''perhaps in about 450BC'') falls in the 500 BC - 1 AD bucket, not the stored 1500 - 500 BC bucket, and no second independent source dates the start, so the field is cleared rather than kept wrong.", "value_page": null}]'::jsonb),
    ('04c8399c-298d-41ab-bb53-f56beb9e45da'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s001-rollback:04c8399c-298d-41ab-bb53-f56beb9e45da:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Fortress/citadel'' restored on Gaer, Black Mountains', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2387", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2387", "quote": "The monument comprises the remains of a hillfort, which probably dates to the Iron Age period", "outcome": "found"}, {"source": "https://www.theguardian.com/science/2008/feb/14/archaeology", "url": "https://www.theguardian.com/science/2008/feb/14/archaeology", "quote": "At Twyn-y-Gaer Allan revealed for the first time in south Wales the complex history of an Iron Age hill fort.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0154)", "decision": "replace", "status": "CONFLICT", "reasoning": "Cadw''s scheduled monument record MM148 and the Guardian obituary of its excavator both call Twyn-y-Gaer an Iron Age hillfort (hill fort); it is a defended hilltop enclosure, i.e. a fort, not a fortress or citadel.", "value_page": null}]'::jsonb),
    ('04c8399c-298d-41ab-bb53-f56beb9e45da'::uuid, 'source_url', 'https://coflein.gov.uk/en/sites/300043', 'https://en.wikipedia.org/wiki/Gaer_(Black_Mountains)', 'fields-wd1-2026-09-26b-s001-rollback:04c8399c-298d-41ab-bb53-f56beb9e45da:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Gaer_(Black_Mountains)'' restored on Gaer, Black Mountains', '[{"source": "https://coflein.gov.uk/en/sites/300043", "url": "https://coflein.gov.uk/en/sites/300043", "quote": "Twn-y-Gaer Camp is a strongly embanked and ditched enclosure occupying the summit of an isolated and dramatic hill.", "outcome": "found"}, {"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2387", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2387", "quote": "Name Twyn-y-Gaer Camp Date of Designation 23/10/1956", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Gaer_(Black_Mountains)", "url": "https://en.wikipedia.org/wiki/Gaer_(Black_Mountains)", "quote": "Gaer (Black Mountains)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0154)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English Wikipedia article is about the hill Gaer, whose summit holds the Iron Age hillfort Twyn y Gaer; the Coflein (RCAHMW) record NPRN 300043 for Twyn-y-Gaer Camp, Crucorney, Monmouthshire (grid reference SO2939021950, the same point as the stored one) is about the hillfort itself, and Cadw''s scheduled monument MM148 independently names the same Twyn-y-Gaer Camp.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('04cdaa66-9cc6-4135-b4b6-ae0f3dbcef2d'::uuid, 'period_name', '500 - 1000 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s001-rollback:04cdaa66-9cc6-4135-b4b6-ae0f3dbcef2d:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1 - 500 AD'' restored on Nevado de Toluca', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(650) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('04cdaa66-9cc6-4135-b4b6-ae0f3dbcef2d'::uuid, 'period_start', '650', '1', 'fields-wd1-2026-09-26b-s001-rollback:04cdaa66-9cc6-4135-b4b6-ae0f3dbcef2d:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1'' restored on Nevado de Toluca', '[{"source": "https://en.wikipedia.org/wiki/Nevado_de_Toluca", "url": "https://en.wikipedia.org/wiki/Nevado_de_Toluca", "quote": "found artifacts dating from the Epi-Classic (650-900 AD) and Post-Classic (900-1200 AD) periods", "outcome": "found"}, {"source": "https://artdaily.cc/news/59798/Archaeologists-discover-objects--more-than-700-years-old--at-Nevado-de-Toluca-in-Mexico", "url": "https://artdaily.cc/news/59798/Archaeologists-discover-objects--more-than-700-years-old--at-Nevado-de-Toluca-in-Mexico", "quote": "As a place for worship, Nevado de Toluca was frequented from (at least) the year 650 to 900 AD (Late Classic period)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0097)", "decision": "replace", "status": "MISSING", "reasoning": "The INAH excavations reported by Wikipedia and by Artdaily date the earliest ritual use of the crater to the Epiclassic from AD 650, which lies in the 500 - 1000 AD bucket, not the stored 1 - 500 AD one.", "value_page": null}]'::jsonb),
    ('051aa298-6b64-49ef-af78-efb53fa1d3a1'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s001-rollback:051aa298-6b64-49ef-af78-efb53fa1d3a1:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1 - 500 AD'' restored on Siga', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-400) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('051aa298-6b64-49ef-af78-efb53fa1d3a1'::uuid, 'period_start', '-400', '1', 'fields-wd1-2026-09-26b-s001-rollback:051aa298-6b64-49ef-af78-efb53fa1d3a1:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1'' restored on Siga', '[{"source": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0006:entry=siga", "url": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0006:entry=siga", "quote": "Siga was the capital of the kingdom of Syphax, mentioned during the 4th c. in the Periplus.", "outcome": "found"}, {"source": "https://journals.openedition.org/encyclopedieberbere/4380?lang=en", "url": "https://journals.openedition.org/encyclopedieberbere/4380?lang=en", "quote": "Siga connut certainement une activité portuaire soutenue au moment de l’installation des Barcides en Espagne à partir de 237 avant J.-C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "MISSING", "reasoning": "The Princeton Encyclopedia of Classical Sites says Siga, Syphax''s capital, is first mentioned in the 4th-century BC Periplus (of Pseudo-Scylax), and the Encyclopédie berbère (J.-P. Laporte) dates that mention to the mid-4th century BC and follows the Punic port from 237 BC; the CNR Algeria Punica text adds pottery of the 5th-4th century BC on virgin soil. The start is the 4th century BC (-400), not the stored AD 1.", "value_page": null}]'::jsonb),
    ('051aa298-6b64-49ef-af78-efb53fa1d3a1'::uuid, 'site_type', 'City', 'Port', 'fields-wd1-2026-09-26b-s001-rollback:051aa298-6b64-49ef-af78-efb53fa1d3a1:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Port'' restored on Siga', '[{"source": "http://cherchel-project.isma.cnr.it/index.php?option=com_content&view=article&id=67&Itemid=48&lang=it", "url": "http://cherchel-project.isma.cnr.it/index.php?option=com_content&view=article&id=67&Itemid=48&lang=it", "quote": "La città di Siga (l’attuale Takembrit", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Siga", "url": "https://en.wikipedia.org/wiki/Siga", "quote": "After a temporary decline, the city got some importance inside the Roman Africa, especially with African emperors", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "Siga at Takembrit is the ruined town that was the capital of Syphax''s Masaesylian kingdom and later a Roman town (acropolis, baths, necropolis, royal mausoleum across the Tafna); the CNR project and Wikipedia describe it as a city. Its river port has never been found, so ''Port'' names only one function, not the site.", "value_page": null}]'::jsonb),
    ('0576c316-4e26-4342-bc7e-42ae84bdc36e'::uuid, 'period_name', '3000 - 1500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s001-rollback:0576c316-4e26-4342-bc7e-42ae84bdc36e:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 BC - 1 AD'' restored on Ancient City of Troy', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0576c316-4e26-4342-bc7e-42ae84bdc36e'::uuid, 'period_start', '-3000', '-500', 'fields-wd1-2026-09-26b-s001-rollback:0576c316-4e26-4342-bc7e-42ae84bdc36e:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-500'' restored on Ancient City of Troy', '[{"source": "https://en.wikipedia.org/wiki/Troy", "url": "https://en.wikipedia.org/wiki/Troy", "quote": "Troy I was founded around 3000 BC on what was then the eastern shore of a shallow lagoon.", "outcome": "found"}, {"source": "https://www.worldhistory.org/troy/", "url": "https://www.worldhistory.org/troy/", "quote": "Inhabited from the Early Bronze Age (3000 BCE) through to the 12th century CE the archaeological site which is now called Troy is 5 km from the coast but was once next to the sea.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0140)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the World History Encyclopedia both date the foundation of the first walled settlement at Troy (Troy I) to c. 3000 BC; the stored -500 is far too late, and the earlier ''Troy 0'' (c. 3600 BC) is only tentatively dated from a few sherds, so the securely attested start is -3000.", "value_page": null}]'::jsonb),
    ('05afa876-bd9b-4285-8aa3-cb1f71fb3707'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s001-rollback:05afa876-bd9b-4285-8aa3-cb1f71fb3707:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''4500 - 3000 BC'' restored on Ərəbyengicə', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('05afa876-bd9b-4285-8aa3-cb1f71fb3707'::uuid, 'period_start', NULL, '-4000', 'fields-wd1-2026-09-26b-s001-rollback:05afa876-bd9b-4285-8aa3-cb1f71fb3707:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-4000'' restored on Ərəbyengicə', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "clear", "status": "MISSING", "reasoning": "The sources disagree on the start: Wikipedia (en/az, after the Nakhchivan Encyclopedia and Baxşəliyev 2008) says ''The settlement belongs to the 4th and 3rd millenniums BC'', while the Azerbaijan National Encyclopedia dates it to ''e.ә. 5-ci–3-cü minilliklәrә'' (5th-3rd millennia BC); Abedi et al. 2015 only call its pottery Late Chalcolithic, so no two independent sources give the same start.", "value_page": null}]'::jsonb),
    ('05c89db6-7e37-495d-9859-544bc6cb60e0'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s001-rollback:05c89db6-7e37-495d-9859-544bc6cb60e0:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1 - 500 AD'' restored on Ayawayq''u', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('05c89db6-7e37-495d-9859-544bc6cb60e0'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s001-rollback:05c89db6-7e37-495d-9859-544bc6cb60e0:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1'' restored on Ayawayq''u', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0106)", "decision": "clear", "status": "MISSING", "reasoning": "Hostnig (rupestreweb.info) classes the paintings as late or Inca rock art associated with Inca-period funerary structures but gives no year or century, and no other source dates the site; the stored 1 AD is unsupported, so the field is emptied.", "value_page": null}]'::jsonb),
    ('05d4e028-3cd3-46e8-ad35-aaaf70a3077c'::uuid, 'site_type', 'Tomb', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s001-rollback:05d4e028-3cd3-46e8-ad35-aaaf70a3077c:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Necropolis/tombs complex'' restored on Heroon of Trysa', '[{"source": "https://en.wikipedia.org/wiki/Heroon_of_Trysa", "url": "https://en.wikipedia.org/wiki/Heroon_of_Trysa", "quote": "The Heroon of Trysa is the modern name for an ancient tomb, built around 380 BCE in Trysa", "outcome": "found"}, {"source": "https://www.worldhistory.org/article/1584/the-heroon-of-trysa-a-lycian-tomb-reappears/", "url": "https://www.worldhistory.org/article/1584/the-heroon-of-trysa-a-lycian-tomb-reappears/", "quote": "The Heroon of Trysa was the tomb of a powerful Lycian dynast surrounded by a precinct wall covered with remarkable mythological friezes.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0144)", "decision": "replace", "status": "CONFLICT", "reasoning": "The heroon is a single monument, the walled tomb of a Lycian dynast, not a necropolis or complex of tombs; Wikipedia and World History Encyclopedia both call it a tomb, so the type is Tomb.", "value_page": null}]'::jsonb),
    ('0688bc28-0762-4ebb-b7b4-770340c2ff18'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s001-rollback:0688bc28-0762-4ebb-b7b4-770340c2ff18:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''4500 - 3000 BC'' restored on Nine Maidens Stone Circle', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0688bc28-0762-4ebb-b7b4-770340c2ff18'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s001-rollback:0688bc28-0762-4ebb-b7b4-770340c2ff18:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-4500'' restored on Nine Maidens Stone Circle', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0042)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, the Megalithic Portal, Britain Express and Legendary Dartmoor call it a Bronze Age stone circle or cairn circle but none gives a year, century or millennium for its construction; the stored 4500 BC contradicts that Bronze Age attribution, and no two readable sources date the start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('0689fd2e-b56c-4c35-adb5-e4ef34083174'::uuid, 'site_type', 'Palace', 'City/town/settlement', 'fields-wd1-2026-09-26b-s001-rollback:0689fd2e-b56c-4c35-adb5-e4ef34083174:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''City/town/settlement'' restored on Vitcos', '[{"source": "https://en.wikipedia.org/wiki/Vitcos", "url": "https://en.wikipedia.org/wiki/Vitcos", "quote": "The palace itself consists of two groups of buildings.", "outcome": "found"}, {"source": "https://www.apacheta.fr/en/blog/inca-city-of-vitcos", "url": "https://www.apacheta.fr/en/blog/inca-city-of-vitcos", "quote": "This palace would have been, for many years, the provincial capital of Vilcabamba.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0115)", "decision": "replace", "status": "MISSING", "reasoning": "Vitcos (Rosaspata) was a residence of Inca nobles whose outstanding feature is the Inca palace. Wikipedia describes the palace''s two building groups, and the Apacheta guide calls it a palace that served as the provincial capital. Palace is more specific than the stored City/town/settlement.", "value_page": null}]'::jsonb),
    ('069317ea-0971-47f0-acf2-306fb08a9ab2'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s001-rollback:069317ea-0971-47f0-acf2-306fb08a9ab2:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1500 - 500 BC'' restored on Megalitikum Rindu Hati', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('069317ea-0971-47f0-acf2-306fb08a9ab2'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s001-rollback:069317ea-0971-47f0-acf2-306fb08a9ab2:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-1500'' restored on Megalitikum Rindu Hati', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0078)", "decision": "clear", "status": "MISSING", "reasoning": "No readable source dates the Rindu Hati site itself: the Megalithic Portal, the Lahat tourism pages and Kompas give no date for it, and the regional statements about Pasemah megaliths (1,000-1,400 or 2,000-3,000 years ago) are neither site-specific nor readable as dates, so the stored 1500 BC is emptied.", "value_page": null}]'::jsonb),
    ('069317ea-0971-47f0-acf2-306fb08a9ab2'::uuid, 'site_type', 'Sculptured stone', 'Megalithic statues', 'fields-wd1-2026-09-26b-s001-rollback:069317ea-0971-47f0-acf2-306fb08a9ab2:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Megalithic statues'' restored on Megalitikum Rindu Hati', '[{"source": "https://www.megalithic.co.uk/article.php?sid=63737", "url": "https://www.megalithic.co.uk/article.php?sid=63737", "quote": "A tight cluster of sculpted stones, as usually for this region representing human like forms.", "outcome": "found"}, {"source": "https://eajournals.org/wp-content/uploads/Pasemah-Sculptures-Monuments-of-the-Existence-and-Worship-of-Ancestor-Spirits.pdf", "url": "https://eajournals.org/wp-content/uploads/Pasemah-Sculptures-Monuments-of-the-Existence-and-Worship-of-Ancestor-Spirits.pdf", "quote": "Gaya dan Nilai-Nilai Pemahat Batu pada Arca Megalitik di Situs Rindu Hati Kecamatan Gumay Ulu", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0078)", "decision": "replace", "status": "MISSING", "reasoning": "The Megalithic Portal classifies the Rindu Hati complex as a Sculptured Stone site, a tight cluster of sculpted stones representing human-like forms, and Indriastuti''s 2011 Balai Arkeologi Palembang study (cited in the Pasemah Sculptures paper) is about the stone carvers of its megalithic statues (arca megalitik); no readable source uses the English words of ''Megalithic statues'' for this site, so the sourced type is Sculptured stone.", "value_page": null}]'::jsonb),
    ('069317ea-0971-47f0-acf2-306fb08a9ab2'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=63737', 'https://kebudayaan-kemdikbud-go-id.translate.goog/bpcbjambi/situs-rindu-hati/?_x_tr_sl=id&_x_tr_tl=en&_x_tr_hl=en&_x_tr_pto=sc', 'fields-wd1-2026-09-26b-s001-rollback:069317ea-0971-47f0-acf2-306fb08a9ab2:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://kebudayaan-kemdikbud-go-id.translate.goog/bpcbjambi/situs-rindu-hati/?_x_tr_sl=id&_x_tr_tl=en&_x_tr_hl=en&_x_tr_pto=sc'' restored on Megalitikum Rindu Hati', '[{"source": "https://www.megalithic.co.uk/article.php?sid=63737", "url": "https://www.megalithic.co.uk/article.php?sid=63737", "quote": "Site Name: Rindu Hati Complex", "outcome": "found"}, {"source": "https://www.kompas.com/stori/read/2023/05/07/150000679/peninggalan-megalitik-di-negeri-seribu-megalit-sumatera-selatan", "url": "https://www.kompas.com/stori/read/2023/05/07/150000679/peninggalan-megalitik-di-negeri-seribu-megalit-sumatera-selatan", "quote": "Beberapa situs megalit di kabupaten lahat adalah Situs Tanjung Sirih, Situs Pulaupanggung, Situs Rindu Hati, Situs Tinggihari 1", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0078)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a Google Translate proxy of a BPCB Jambi page whose domain (kebudayaan.kemdikbud.go.id) no longer resolves, so it returns 404; the Megalithic Portal''s Rindu Hati Complex entry loads as plain HTML and is about this statue group, and Kompas independently names the Rindu Hati site among Lahat''s megalithic sites.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('069e0320-14f7-497f-8239-4ffb969049c1'::uuid, 'source_url', 'https://de.wikipedia.org/wiki/Id%C3%A4ische_Grotte', 'https://en.wikipedia.org/wiki/Psychro_Cave', 'fields-wd1-2026-09-26b-s001-rollback:069e0320-14f7-497f-8239-4ffb969049c1:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Psychro_Cave'' restored on Idaean Cave', '[{"source": "https://de.wikipedia.org/wiki/Id%C3%A4ische_Grotte", "url": "https://de.wikipedia.org/wiki/Id%C3%A4ische_Grotte", "quote": "Die Idäische Grotte gilt, wie die Diktäische Grotte bei Psychro, als Geburtsort des Zeus Kretagenes.", "outcome": "found"}, {"source": "https://www.archaeology.wiki/blog/2021/06/24/inspection-of-the-idaean-cave/", "url": "https://www.archaeology.wiki/blog/2021/06/24/inspection-of-the-idaean-cave/", "quote": "The Idaean Cave is located on the eastern slopes of Mount Ida, on the Nida plateau, at an altitude of 1,498 m. and 20 km away from Anogia.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the Psychro (Dictaean) Cave, a different site, and English Wikipedia''s Idaean Cave title only redirects there; the German Wikipedia article is about the Idaean Cave on Mount Ida itself.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Idäische Grotte", "unreadable": false, "wikibase_item": "Q935991"}}]'::jsonb),
    ('06a1c527-b9cc-44f8-a8a2-7d9510d1c5b0'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s001-rollback:06a1c527-b9cc-44f8-a8a2-7d9510d1c5b0:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 BC - 1 AD'' restored on Ngarrabullgan', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('06a1c527-b9cc-44f8-a8a2-7d9510d1c5b0'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s001-rollback:06a1c527-b9cc-44f8-a8a2-7d9510d1c5b0:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-500'' restored on Ngarrabullgan', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, the Ngarrabullgan project site, the Pama Language Centre and the published excavation reports date the first occupation of Ngarrabullgan Cave only as c. 37,000 years ago / 37,170 BP or 40,000+ years ago; no source states a calendar year, century or millennium BC, and the stored 500 BC is plainly wrong, so the field is emptied.", "value_page": null}]'::jsonb),
    ('06a1c527-b9cc-44f8-a8a2-7d9510d1c5b0'::uuid, 'site_type', 'Sacred site', 'Cave Structures', 'fields-wd1-2026-09-26b-s001-rollback:06a1c527-b9cc-44f8-a8a2-7d9510d1c5b0:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Cave Structures'' restored on Ngarrabullgan', '[{"source": "https://www.ngarrabullgan.com.au/", "url": "https://www.ngarrabullgan.com.au/", "quote": "Ngarrabullgan, previously known under its colonial name Mount Mulligan, is a sacred Djungan site in Queensland, Australia", "outcome": "found"}, {"source": "https://www.pamacentre.org.au/oldest-sites-ngarrabullgan/", "url": "https://www.pamacentre.org.au/oldest-sites-ngarrabullgan/", "quote": "Ngarrabullgan is a large tabletop mountain about 100km west of Cairns. It is the oldest cultural site we know people have used in Queensland. Scientists think that people have been using the rock shelters called Ngarrabullgan Cave and Nonda Rock for at least 40,000 years. Still today it is a sacred place for the traditional owners, the Kuku Djungan people.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "Ngarrabullgan (Mount Mulligan, Queensland) is a tabletop mountain that two independent sources call a sacred site or place of the Djungan people; its caves and rock shelters (Ngarrabullgan Cave, Nonda Rock) lie on the mountain, so the site as a whole is a sacred site, not a cave structure.", "value_page": null}]'::jsonb),
    ('06a73089-340c-40ac-9979-4a5c08f93da5'::uuid, 'site_type', 'Fort', 'Mine/quarry', 'fields-wd1-2026-09-26b-s001-rollback:06a73089-340c-40ac-9979-4a5c08f93da5:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Mine/quarry'' restored on Cissbury Ring', '[{"source": "https://en.wikipedia.org/wiki/Cissbury_Ring", "url": "https://en.wikipedia.org/wiki/Cissbury_Ring", "quote": "Cissbury Ring is the largest hill fort in Sussex", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=50", "url": "https://www.megalithic.co.uk/article.php?sid=50", "quote": "County: West Sussex Type: Hillfort Nearest Town: Worthing Nearest Village: Findon", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0031)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Megalithic Portal describe Cissbury Ring itself as an Iron Age hill fort whose interior contains the older flint mines; the named site and the stored point are the ring of the fort, so Fort is the most specific type.", "value_page": null}]'::jsonb),
    ('06b8aeb4-f8fd-4ec0-aa49-a450dd924df0'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s001-rollback:06b8aeb4-f8fd-4ec0-aa49-a450dd924df0:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''3000 - 1500 BC'' restored on Parc Cwm Long Cairn', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3900) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('06b8aeb4-f8fd-4ec0-aa49-a450dd924df0'::uuid, 'period_start', '-3900', '-3000', 'fields-wd1-2026-09-26b-s001-rollback:06b8aeb4-f8fd-4ec0-aa49-a450dd924df0:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-3000'' restored on Parc Cwm Long Cairn', '[{"source": "https://en.wikipedia.org/wiki/Parc_Cwm_long_cairn", "url": "https://en.wikipedia.org/wiki/Parc_Cwm_long_cairn", "quote": "c. 3900 BC", "outcome": "found"}, {"source": "https://coflein.gov.uk/en/sites/93072", "url": "https://coflein.gov.uk/en/sites/93072", "quote": "The tomb was in use for as long as 800 years, from 3800 BC, or for as little as 300 years.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0155)", "decision": "replace", "status": "MISSING", "reasoning": "Parc Cwm long cairn (Parc le Breos, Gower) is an early Neolithic Severn-Cotswold chambered tomb: the English Wikipedia infobox gives ''Built c. 3900 BC'' and the RCAHMW Coflein record (NPRN 93072), citing the radiocarbon dating programme, says the tomb was in use from 3800 BC. Both put the start in the 4500 - 3000 BC bucket, not the stored 3000 - 1500 BC one, so the start is replaced by -3900.", "value_page": null}]'::jsonb),
    ('070dcea0-d528-4f58-bd97-7b3ad5a5d73e'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s001-rollback:070dcea0-d528-4f58-bd97-7b3ad5a5d73e:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 BC - 1 AD'' restored on Tilurium', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('070dcea0-d528-4f58-bd97-7b3ad5a5d73e'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s001-rollback:070dcea0-d528-4f58-bd97-7b3ad5a5d73e:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-500'' restored on Tilurium', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0018)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and the University of Zagreb RoMiCRO project page say the Roman legionary camp at Gardun was built on the site of an earlier Illyrian (Delmatae) hillfort, but no source dates that hillfort by year, century or millennium; the only dated phase, the Roman fortress of the early 1st century AD, is not the site''s start, so the start cannot be sourced and the field is emptied.", "value_page": null}]'::jsonb),
    ('070dcea0-d528-4f58-bd97-7b3ad5a5d73e'::uuid, 'site_type', 'Fortress', 'City/town/settlement', 'fields-wd1-2026-09-26b-s001-rollback:070dcea0-d528-4f58-bd97-7b3ad5a5d73e:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''City/town/settlement'' restored on Tilurium', '[{"source": "https://en.wikipedia.org/wiki/Tilurium", "url": "https://en.wikipedia.org/wiki/Tilurium", "quote": "it later became a major Roman legionary fortress and continued as a fortified post into Late Antiquity", "outcome": "found"}, {"source": "https://www.jaha.org.ro/index.php/JAHA/article/view/370", "url": "https://www.jaha.org.ro/index.php/JAHA/article/view/370", "quote": "The legionary fortress of Tilurium (village of Gardun near Trilj in Croatia) has been the subject of archaeological excavations from 1997", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0018)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Cesarik''s article in the Journal of Ancient History and Archaeology both describe Tilurium at Gardun as a Roman legionary fortress; Fortress is more specific and accurate than City/town/settlement.", "value_page": null}]'::jsonb),
    ('076be159-500d-490f-b804-aea33c1160e9'::uuid, 'period_name', NULL, '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s001-rollback:076be159-500d-490f-b804-aea33c1160e9:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1000 - 1500 AD'' restored on Inka Tampu, Vilcabamba', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('076be159-500d-490f-b804-aea33c1160e9'::uuid, 'period_start', NULL, '1000', 'fields-wd1-2026-09-26b-s001-rollback:076be159-500d-490f-b804-aea33c1160e9:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1000'' restored on Inka Tampu, Vilcabamba', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0109)", "decision": "clear", "status": "MISSING", "reasoning": "The sources describe Inka Tampu only as an Inca building (a wayrana used as a high-altitude shrine) without any date for its construction, so no two sources date its start and the field is emptied.", "value_page": null}]'::jsonb),
    ('0784c790-17b2-4450-9a95-286c1d9ef2f2'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s001-rollback:0784c790-17b2-4450-9a95-286c1d9ef2f2:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''4500 - 3000 BC'' restored on Domus De Janas Torre Argentina', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0784c790-17b2-4450-9a95-286c1d9ef2f2'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s001-rollback:0784c790-17b2-4450-9a95-286c1d9ef2f2:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-4500'' restored on Domus De Janas Torre Argentina', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0084)", "decision": "clear", "status": "MISSING", "reasoning": "The sources for this site (IDESE, nuraghi.net/Nurnet) only call the tombs prehistoric and note later reuse; no source dates these two domus de janas, and the general dating of the tomb type is not evidence for this site, so the field is emptied.", "value_page": null}]'::jsonb),
    ('0784c790-17b2-4450-9a95-286c1d9ef2f2'::uuid, 'site_type', 'Tomb', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s001-rollback:0784c790-17b2-4450-9a95-286c1d9ef2f2:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Necropolis/tombs complex'' restored on Domus De Janas Torre Argentina', '[{"source": "https://nuraghi.net/domus-de-janas-di-torre-argentina-i", "url": "https://nuraghi.net/domus-de-janas-di-torre-argentina-i", "quote": "Domus isolata con riutilizzo.", "outcome": "found"}, {"source": "https://it.wikipedia.org/wiki/Bosa", "url": "https://it.wikipedia.org/wiki/Bosa", "quote": "Di età preistorica e protostorica sono le numerose domus de janas (almeno trentasei) presenti in varie località del comune di Bosa (Badde Orca, Capitta, Coroneddu, Funtana Lacos, Ispiluncas, Monte Furru, Pala ''e Cane, Pontes, Sorighes, Silattari, Tentizzos, Torre Argentina e Tuccaravo).", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Domus_de_janas", "url": "https://en.wikipedia.org/wiki/Domus_de_janas", "quote": "are a type of pre-Nuragic rock-cut chamber tomb found in Sardinia", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0015)", "decision": "replace", "status": "MISSING", "reasoning": "The Torre Argentina site near Bosa (Planargia, Sardinia) is a domus de janas, which nuraghi.net (Nurnet data) records as an isolated domus (''Domus isolata con riutilizzo''), not a group; the Italian Wikipedia lists Torre Argentina among the Bosa localities with domus de janas, and English Wikipedia defines a domus de janas as a rock-cut chamber tomb. A single rock-cut tomb is ''Tomb'', not a necropolis or tombs complex.", "value_page": null}]'::jsonb),
    ('07892a09-1ce0-440e-8300-9f097e3be591'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s001-rollback:07892a09-1ce0-440e-8300-9f097e3be591:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 BC - 1 AD'' restored on Lezhë District', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-800) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('07892a09-1ce0-440e-8300-9f097e3be591'::uuid, 'period_start', '-800', '-500', 'fields-wd1-2026-09-26b-s001-rollback:07892a09-1ce0-440e-8300-9f097e3be591:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-500'' restored on Lezhë District', '[{"source": "https://en.wikipedia.org/wiki/Lezh%C3%AB", "url": "https://en.wikipedia.org/wiki/Lezh%C3%AB", "quote": "The settlement with its fortifications was built on a 413-metre-high mountain, the Mal i Shëlbuemit, from at least the 8th century BC", "outcome": "found"}, {"source": "https://albanopedia.com/ancient-states-regions/lissus", "url": "https://albanopedia.com/ancient-states-regions/lissus", "quote": "There was already an Illyrian town over the hill of Lissus since the sixth century B.C.E., apparently from founders who descended from Acrolissus.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia dates the Iron Age fortified settlement of Acrolissus, from which the city of Lissus grew in continuous transition, to at least the 8th century BC, and Albanopedia dates the Illyrian town on the hill of Lissus itself to the 6th century BC, founded from Acrolissus; the start therefore lies in the 1500-500 BC bucket, not in 500 BC - 1 AD, and is set at the 8th century BC.", "value_page": null}]'::jsonb),
    ('07892a09-1ce0-440e-8300-9f097e3be591'::uuid, 'site_type', 'City', 'Megalithic stones', 'fields-wd1-2026-09-26b-s001-rollback:07892a09-1ce0-440e-8300-9f097e3be591:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Megalithic stones'' restored on Lezhë District', '[{"source": "https://albanopedia.com/ancient-states-regions/lissus", "url": "https://albanopedia.com/ancient-states-regions/lissus", "quote": "Lissus or Lissos was an ancient city located in the current city of Lezha on the northwestern Albanian coast.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Lezh%C3%AB", "url": "https://en.wikipedia.org/wiki/Lezh%C3%AB", "quote": "the proper city of Lissus was built on an adjacent hill (172 m high, left).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is ancient Lissus, which Albanopedia and Wikipedia describe as an ancient city with Illyrian fortification walls; its large-block walls do not make it a megalithic-stones site.", "value_page": null}]'::jsonb),
    ('07892a09-1ce0-440e-8300-9f097e3be591'::uuid, 'source_url', NULL, 'https://en.wikipedia.org/wiki/Lezh%C3%AB', 'fields-wd1-2026-09-26b-s001-rollback:07892a09-1ce0-440e-8300-9f097e3be591:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Lezh%C3%AB'' restored on Lezhë District', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "clear", "status": "CONFLICT", "reasoning": "The stored page is the English article on the modern city of Lezhë and ''Lezhë District'' is a former administrative district, neither of them a page about this site; the ancient city behind the entry (Lissus) has pages such as Albanian Wikipedia ''Lisi (qytet)'', but none names the site as the entry does, so no page can be sourced for it.", "value_page": null}]'::jsonb),
