    ('08088896-dddb-43de-a2d3-188c2cf4f61a'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s001-rollback:08088896-dddb-43de-a2d3-188c2cf4f61a:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''3000 - 1500 BC'' restored on Bølareinen', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4000) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('08088896-dddb-43de-a2d3-188c2cf4f61a'::uuid, 'period_start', '-4000', '-3000', 'fields-wd1-2026-09-26b-s001-rollback:08088896-dddb-43de-a2d3-188c2cf4f61a:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-3000'' restored on Bølareinen', '[{"source": "https://andersgoliversen.com/2023/08/02/bola-petroglyphs/", "url": "https://andersgoliversen.com/2023/08/02/bola-petroglyphs/", "quote": "The site is usually dated to have been carved ca. 4000-3000 BCE during the Nordic Stone Age", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/B%C3%B8lareinen", "url": "https://en.wikipedia.org/wiki/B%C3%B8lareinen", "quote": "The carvings are dated to 3400–3200 years BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0102)", "decision": "replace", "status": "MISSING", "reasoning": "One source dates the Bøla carvings to ca. 4000-3000 BCE, and Wikipedia to 3400-3200 BCE. Both put the start in the 4500-3000 BC bucket, not in the stored 3000-1500 BC bucket, so the value becomes c. 4000 BC.", "value_page": null}]'::jsonb),
    ('086aa9b8-6e6e-492d-baf2-a829b5eb0f6c'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s001-rollback:086aa9b8-6e6e-492d-baf2-a829b5eb0f6c:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Fortress/citadel'' restored on Jenny''s Lantern', '[{"source": "https://www.megalithic.co.uk/article.php?sid=33967", "url": "https://www.megalithic.co.uk/article.php?sid=33967", "quote": "An Iron Age fort and Romano-British settlement are located near the ruins of Jenny''s Lantern, SE of Eglingham.", "outcome": "found"}, {"source": "https://keystothepast.info/search-records/results-of-search/results-of-search-2/Site-Details/?PRN=N4380", "url": "https://keystothepast.info/search-records/results-of-search/results-of-search-2/Site-Details/?PRN=N4380", "quote": "A large multivallate Iron Age fort situated on high ground.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Megalithic Portal and the Northumberland HER both describe the site as a multivallate Iron Age fort (hillfort) with a later Romano-British settlement over it; no source calls it a fortress or citadel, so the specific type is Fort.", "value_page": null}]'::jsonb),
    ('086aa9b8-6e6e-492d-baf2-a829b5eb0f6c'::uuid, 'source_url', 'https://keystothepast.info/search-records/results-of-search/results-of-search-2/Site-Details/?PRN=N4380', 'https://en.wikipedia.org/wiki/Jenny%27s_Lantern', 'fields-wd1-2026-09-26b-s001-rollback:086aa9b8-6e6e-492d-baf2-a829b5eb0f6c:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Jenny%27s_Lantern'' restored on Jenny''s Lantern', '[{"source": "https://keystothepast.info/search-records/results-of-search/results-of-search-2/Site-Details/?PRN=N4380", "url": "https://keystothepast.info/search-records/results-of-search/results-of-search-2/Site-Details/?PRN=N4380", "quote": "Iron Age defended settlement south of Jenny''s Lantern (Hedgeley)", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=33967", "url": "https://www.megalithic.co.uk/article.php?sid=33967", "quote": "An Iron Age fort and Romano-British settlement are located near the ruins of Jenny''s Lantern, SE of Eglingham.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English Wikipedia article is about the Jenny''s Lantern hill and moorland named after an 18th-century folly, with the hillfort only as one section; the Northumberland HER record N4380 on Keys to the Past is the entry for the hillfort itself, which the Megalithic Portal also describes.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('0888887e-7cdb-44aa-8e48-36afb0198623'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s001-rollback:0888887e-7cdb-44aa-8e48-36afb0198623:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Fortress/citadel'' restored on Pen Dinas', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=763", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=763", "quote": "The fort started life as a simple defended site on the north summit, enclosed by a rampart of packed rubble and an outer ditch (Phase I).", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Pen_Dinas", "url": "https://en.wikipedia.org/wiki/Pen_Dinas", "quote": "The hillfort actually consists of two separate forts built many years apart, which were later combined to form a larger structure.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0155)", "decision": "replace", "status": "CONFLICT", "reasoning": "Cadw''s scheduled-monument record (CD007 Pen Dinas Camp, site type Hillfort) and English Wikipedia both describe Pen Dinas as an Iron Age hillfort of two forts later combined; nothing calls it a fortress or citadel, and the hill class of the item is not the site''s type, so the specific canonical type is Fort.", "value_page": null}]'::jsonb),
    ('08f27e9a-8ad4-49b2-8676-a9c7a43cde8b'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s001-rollback:08f27e9a-8ad4-49b2-8676-a9c7a43cde8b:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 BC - 1 AD'' restored on Temple of Khnum- Esna', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1425) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('08f27e9a-8ad4-49b2-8676-a9c7a43cde8b'::uuid, 'period_start', '-1425', '-500', 'fields-wd1-2026-09-26b-s001-rollback:08f27e9a-8ad4-49b2-8676-a9c7a43cde8b:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-500'' restored on Temple of Khnum- Esna', '[{"source": "https://de.wikipedia.org/wiki/Tempel_von_Esna", "url": "https://de.wikipedia.org/wiki/Tempel_von_Esna", "quote": "Der Chnum-Tempel von Esna wurde auf den Ruinen eines früheren Heiligtums aus der 18. Dynastie, spätestens der Zeit Thutmosis III. († 1425 v. Chr.), errichtet.", "outcome": "found"}, {"source": "https://www.nefershapiland.de/esna.htm", "url": "https://www.nefershapiland.de/esna.htm", "quote": "der Tempel des Chnum aus ptolemäischer und römischer Zeit, der an Stelle eines Tempels der 18. Dynastie des Königs Thutmosis III. völlig neu erbaut wurde.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0004)", "decision": "replace", "status": "MISSING", "reasoning": "Two independent sources say the Khnum temple at Esna stands on the site of an earlier 18th Dynasty sanctuary, at the latest of the time of Thutmose III (died 1425 BC), so the site''s attested history starts in the New Kingdom (bucket 1500 - 500 BC), not with the Ptolemaic rebuilding in the stored 500 BC - 1 AD bucket; 1425 BC is the latest date the sources allow for that first temple.", "value_page": null}]'::jsonb),
    ('08f27e9a-8ad4-49b2-8676-a9c7a43cde8b'::uuid, 'site_type', 'Temple', 'Temple complex', 'fields-wd1-2026-09-26b-s001-rollback:08f27e9a-8ad4-49b2-8676-a9c7a43cde8b:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Temple complex'' restored on Temple of Khnum- Esna', '[{"source": "https://en.wikipedia.org/wiki/Temple_of_Esna", "url": "https://en.wikipedia.org/wiki/Temple_of_Esna", "quote": "The Temple of Esna, also known as the Temple of Khnum at Esna, is an ancient Egyptian temple in the city of Esna, about 64 kilometres south of Luxor.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=6336063", "url": "https://www.megalithic.co.uk/article.php?sid=6336063", "quote": "Site Name: Temple of Khnum, Esna Alternative Name: Isna Temple of Knuhm Country: Egypt Region: Upper Egypt (South) Type: Ancient Temple", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0024)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls it an ancient Egyptian temple and the Megalithic Portal types it Ancient Temple; only its hypostyle hall still stands, so it is a single temple rather than a temple complex, and Temple is the most specific type.", "value_page": null}]'::jsonb),
    ('08f27e9a-8ad4-49b2-8676-a9c7a43cde8b'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Temple_of_Esna', 'https://en.wikipedia.org/wiki/Khnum', 'fields-wd1-2026-09-26b-s001-rollback:08f27e9a-8ad4-49b2-8676-a9c7a43cde8b:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Khnum'' restored on Temple of Khnum- Esna', '[{"source": "https://en.wikipedia.org/wiki/Temple_of_Esna", "url": "https://en.wikipedia.org/wiki/Temple_of_Esna", "quote": "The Temple of Esna, also known as the Temple of Khnum at Esna, is an ancient Egyptian temple in the city of Esna, about 64 kilometres south of Luxor.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=6336063", "url": "https://www.megalithic.co.uk/article.php?sid=6336063", "quote": "Site Name: Temple of Khnum, Esna Alternative Name: Isna Temple of Knuhm", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0024)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the article on the god Khnum; the site''s own English Wikipedia article is ''Temple of Esna'', also known as the Temple of Khnum at Esna, and the Megalithic Portal names the same Temple of Khnum at Esna.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Temple of Esna", "unreadable": false, "wikibase_item": "Q1131024"}}]'::jsonb),
    ('0931e87d-b91d-4632-91af-e85c5bdfb2f2'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s001-rollback:0931e87d-b91d-4632-91af-e85c5bdfb2f2:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''4500 - 3000 BC'' restored on Glösa', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0931e87d-b91d-4632-91af-e85c5bdfb2f2'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s001-rollback:0931e87d-b91d-4632-91af-e85c5bdfb2f2:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-4500'' restored on Glösa', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0137)", "decision": "clear", "status": "MISSING", "reasoning": "The dating of the Glösa carvings is loose and inconsistent: the on-site sign quoted by Kulturbilder gives c. 4000-3000 BC, French Wikipedia gives c. 3000 BC, and most other pages give only ''about 5,000/6,000 years ago'' or ''Mesolithic''; no two independent sources state a start year in the same bucket.", "value_page": null}]'::jsonb),
    ('0931e87d-b91d-4632-91af-e85c5bdfb2f2'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=63073', 'https://en.wikipedia.org/wiki/Gl%C3%B6sa', 'fields-wd1-2026-09-26b-s001-rollback:0931e87d-b91d-4632-91af-e85c5bdfb2f2:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Gl%C3%B6sa'' restored on Glösa', '[{"source": "https://www.megalithic.co.uk/article.php?sid=63073", "url": "https://www.megalithic.co.uk/article.php?sid=63073", "quote": "Site Name: Glösa petroglyphs", "outcome": "found"}, {"source": "https://uddautflykter.se/guide/jamtland/krokom/glosa-hallristningar/", "url": "https://uddautflykter.se/guide/jamtland/krokom/glosa-hallristningar/", "quote": "Mer okända, men inte mindre spekakulära är spåren efter det jägarfolk som under stenåldern höll till runt Glösa i Krokom.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0137)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the village of Glösa; the carvings have no Wikipedia article of their own (their Wikidata item Q29380540 links only to Commons) and the RAÄ Fornsök record needs a script, so the Megalithic Portal''s own record of the Glösa petroglyphs is the page about this very site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('09809b93-9c66-424c-ab0e-12cb3052ad31'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s001-rollback:09809b93-9c66-424c-ab0e-12cb3052ad31:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''4500 - 3000 BC'' restored on Condolden', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('09809b93-9c66-424c-ab0e-12cb3052ad31'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s001-rollback:09809b93-9c66-424c-ab0e-12cb3052ad31:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-4500'' restored on Condolden', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0032)", "decision": "clear", "status": "MISSING", "reasoning": "The barrow is unexcavated; the sources date it only to ''the Bronze Age'', and the one page with years (Dark Cornwall) gives the general range of bowl barrows, not of this monument. No two sources date its construction, and the stored Neolithic -4500 is unsupported, so the field is emptied.", "value_page": null}]'::jsonb),
    ('09809b93-9c66-424c-ab0e-12cb3052ad31'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=22301', 'https://en.wikipedia.org/wiki/Condolden', 'fields-wd1-2026-09-26b-s001-rollback:09809b93-9c66-424c-ab0e-12cb3052ad31:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Condolden'' restored on Condolden', '[{"source": "https://www.megalithic.co.uk/article.php?sid=22301", "url": "https://www.megalithic.co.uk/article.php?sid=22301", "quote": "Site Name: Condolden Barrow", "outcome": "found"}, {"source": "https://www.intocornwall.com/engine/azabout.asp?guide=Condolden+Barrow", "url": "https://www.intocornwall.com/engine/azabout.asp?guide=Condolden+Barrow", "quote": "Condolden Barrow stands on Condolden Hill a short distance inland from Tintagel", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0032)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill Condolden, not the barrow on it; the barrow has no Wikipedia article and the Historic England entry refuses automated requests. The Megalithic Portal''s Condolden Barrow page is a readable page about this very monument.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('09833bba-315b-4cd0-866b-a0918a9d3434'::uuid, 'geom', 'SRID=4326;POINT(15.6152 41.654408)', '0101000020E610000011E3232322222F4017188D0F5AD54440', 'fields-wd1-2026-09-26b-s001-rollback:09833bba-315b-4cd0-866b-a0918a9d3434:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E610000011E3232322222F4017188D0F5AD54440'' restored on Paglicci Cave', '[{"source": "https://it.wikipedia.org/wiki/Grotta_Paglicci", "url": "https://it.wikipedia.org/wiki/Grotta_Paglicci", "quote": "41°39′15.87″N 15°36′54.72″E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=42903", "url": "https://www.megalithic.co.uk/article.php?sid=42903", "quote": "Latitude: 41.653748N Longitude: 15.615040E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0086)", "decision": "replace", "status": "CONFLICT", "reasoning": "Italian Wikipedia and the Megalithic Portal both place Grotta Paglicci at about 41.654, 15.615 in località Paglicci (Rignano Garganico); the stored point only copies the rounded 41°40′00″N 15°34′00″E of the English article and lies 4.3 km away near Rignano town, so it is replaced by the cave''s point.", "value_page": null}]'::jsonb),
