    ('0999c397-1333-4ff3-aa26-fe854f46de9c'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Enkomi_(archaeological_site)', 'https://en.wikipedia.org/wiki/Enkomi', 'fields-wd1-2026-09-26b-s001-rollback:0999c397-1333-4ff3-aa26-fe854f46de9c:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Enkomi'' restored on Engomi Ancient City Ruins', '[{"source": "https://en.wikipedia.org/wiki/Enkomi_(archaeological_site)", "url": "https://en.wikipedia.org/wiki/Enkomi_(archaeological_site)", "quote": "Enkomi was settled in the Middle Bronze Age", "outcome": "found"}, {"source": "https://www.culture.gov.cy/dmculture/DA/DA.nsf/All/8DE8559230B6E848C2257276002FA8FB?OpenDocument", "url": "https://www.culture.gov.cy/dmculture/DA/DA.nsf/All/8DE8559230B6E848C2257276002FA8FB?OpenDocument", "quote": "The archaeological site of Enkomi is one of the richest Late Bronze Age sites in Cyprus. This ancient town is situated on the island’s eastern coast, around 3 km to the northwest of Salamis and to the west of the modern village of Engomi in the Ammochostos district.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0019)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the article on the modern village of Enkomi/Engomi (Tuzla); the site''s own English Wikipedia article is ''Enkomi (archaeological site)'', about the Bronze Age town, which the Department of Antiquities independently describes west of the modern village of Engomi.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Enkomi (archaeological site)", "unreadable": false, "wikibase_item": "Q22987223"}}]'::jsonb),
    ('0a05d7ed-33cc-432a-b831-c67cf546593f'::uuid, 'period_name', '500 - 1000 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s001-rollback:0a05d7ed-33cc-432a-b831-c67cf546593f:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1 - 500 AD'' restored on Waithali', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(501) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0a05d7ed-33cc-432a-b831-c67cf546593f'::uuid, 'period_start', '501', '1', 'fields-wd1-2026-09-26b-s001-rollback:0a05d7ed-33cc-432a-b831-c67cf546593f:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1'' restored on Waithali', '[{"source": "https://aboutarakan.blogspot.com/2011/06/ancient-geography-and-recent.html", "url": "https://aboutarakan.blogspot.com/2011/06/ancient-geography-and-recent.html", "quote": "Art history and numismatic studies place Vesali between perhaps the 6th and 10th centuries AD (Nyunt Han 1984; Gutman 2001: 41).", "outcome": "found"}, {"source": "https://pathsunwritten.com/ancient-vesali-myanmar/", "url": "https://pathsunwritten.com/ancient-vesali-myanmar/", "quote": "this style in Vesali aligns it with the 6th Century CE, leading to the most commonly held dates 500-1000 CE", "outcome": "found"}, {"source": "https://rohingyaculturalmemorycentre.iom.int/timeline", "url": "https://rohingyaculturalmemorycentre.iom.int/timeline", "quote": "Power shifted from Dhanyawadi to the city of Vesali which was founded in 788 CE by Maha Taing Candra.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0099)", "decision": "replace", "status": "MISSING", "reasoning": "The archaeologist Bob Hudson (University of Sydney; paper reproduced on this blog) and Paths Unwritten date the city of Vesali/Waithali by its art and coins to the 6th century AD. The chronicle date cited by the IOM Rohingya Cultural Memory Centre, 788 CE, falls in the same 500-1000 AD bucket. The 327/370 dates are local tradition, and Hudson ties the 370 walled city to Dhanyawadi, so the stored 1-500 AD bucket is not supported.", "value_page": null}]'::jsonb),
    ('0a6e70ea-022a-4035-a866-0e54efff533d'::uuid, 'period_name', NULL, '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s001-rollback:0a6e70ea-022a-4035-a866-0e54efff533d:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1000 - 1500 AD'' restored on Wat''a, Cusco', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0a6e70ea-022a-4035-a866-0e54efff533d'::uuid, 'period_start', NULL, '1400', 'fields-wd1-2026-09-26b-s001-rollback:0a6e70ea-022a-4035-a866-0e54efff533d:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1400'' restored on Wat''a, Cusco', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0115)", "decision": "clear", "status": "MISSING", "reasoning": "The sources describe Wat''a as a pre-Inca settlement later occupied by the Inca, with Early Horizon/Formative material (MINCETUR, DDC Cusco), but none gives a year or century for its start. The stored 1400 is unsupported, so the field is emptied.", "value_page": null}]'::jsonb),
    ('0b8a8edd-8a60-4758-985c-bf354de4a985'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s001-rollback:0b8a8edd-8a60-4758-985c-bf354de4a985:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''4500 - 3000 BC'' restored on King Lud''s Entrenchments and The Drift', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0b8a8edd-8a60-4758-985c-bf354de4a985'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s001-rollback:0b8a8edd-8a60-4758-985c-bf354de4a985:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-4500'' restored on King Lud''s Entrenchments and The Drift', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia says the earthwork ''has not been excavated and its date is unknown'' (once thought Saxon, now possibly part of a prehistoric boundary system) and the Megalithic Portal files it as ''Date Uncertain''; the Early Bronze Age date belongs to the adjacent barrow, not the earthwork. No source dates the start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('0bee1a58-01b6-4d51-8caa-782b194828fb'::uuid, 'site_type', 'Burial', 'Cemetery', 'fields-wd1-2026-09-26b-s001-rollback:0bee1a58-01b6-4d51-8caa-782b194828fb:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Cemetery'' restored on Stenungsund', '[{"source": "https://en.wikipedia.org/wiki/Stenungsund", "url": "https://en.wikipedia.org/wiki/Stenungsund", "quote": "Archaeological excavations in Stenungsund in 2006 discovered a site of Iron Age burials", "outcome": "found"}, {"source": "https://www.upi.com/Science_News/2006/11/09/Roman-artifacts-found-in-Swedish-graves/33991163099818/", "url": "https://www.upi.com/Science_News/2006/11/09/Roman-artifacts-found-in-Swedish-graves/33991163099818/", "quote": "Shards of Roman ceramics found in ancient graves in western Sweden suggest there was more contact between the Romans and Swedes than thought.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0137)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is two Roman Iron Age graves (burned bones of two people with Roman pottery) found beside a settlement, not a cemetery; Wikipedia calls it a site of Iron Age burials and UPI ancient graves, so Burial is the most specific type that holds.", "value_page": null}]'::jsonb),
    ('0bee1a58-01b6-4d51-8caa-782b194828fb'::uuid, 'source_url', 'https://www.kringla.nu/kringla/objekt?referens=raa/lamning/7ee410f9-1a2a-45cf-a1bf-149d67b9f2c1', 'https://en.wikipedia.org/wiki/Stenungsund', 'fields-wd1-2026-09-26b-s001-rollback:0bee1a58-01b6-4d51-8caa-782b194828fb:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Stenungsund'' restored on Stenungsund', '[{"source": "https://www.kringla.nu/kringla/objekt?referens=raa/lamning/7ee410f9-1a2a-45cf-a1bf-149d67b9f2c1", "url": "https://www.kringla.nu/kringla/objekt?referens=raa/lamning/7ee410f9-1a2a-45cf-a1bf-149d67b9f2c1", "quote": "Grav- och boplatsområde, undersökt och borttagen år 2006, ca 200x110 m (N-S).", "outcome": "found"}, {"source": "https://www.kringla.nu/kringla/objekt?referens=raa/lamning/7ee410f9-1a2a-45cf-a1bf-149d67b9f2c1", "url": "https://www.kringla.nu/kringla/objekt?referens=raa/lamning/7ee410f9-1a2a-45cf-a1bf-149d67b9f2c1", "quote": "Belägen i Norum, Stenungsund, Bohuslän, Västra Götaland.", "outcome": "found"}, {"source": "https://www.upi.com/Science_News/2006/11/09/Roman-artifacts-found-in-Swedish-graves/33991163099818/", "url": "https://www.upi.com/Science_News/2006/11/09/Roman-artifacts-found-in-Swedish-graves/33991163099818/", "quote": "Archaeologists at the site in Stenungsund, around 30 miles north of Gothenburg", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0137)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the town of Stenungsund; the 2006 graves belong to the RAÄ-registered grave and settlement area Norum 202:1, excavated and removed in 2006 (Nordqvist and Lönn, RAÄ dnr 321-4486-2006), whose register entry on Kringla is the page about this very site; UPI''s report on the dig names the same site in Stenungsund.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('0c00d8bd-d6b3-4237-b4c9-9a86748ee5ab'::uuid, 'source_url', 'https://ru.wikipedia.org/wiki/%D0%A2%D0%B5%D0%B0%D1%82%D1%80_%D0%B2_%D0%9A%D1%83%D1%80%D0%B8%D0%BE%D0%BD%D0%B5', 'https://en.wikipedia.org/wiki/Theatre', 'fields-wd1-2026-09-26b-s001-rollback:0c00d8bd-d6b3-4237-b4c9-9a86748ee5ab:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Theatre'' restored on Κourion Ancient Amphitheatre', '[{"source": "https://ru.wikipedia.org/wiki/%D0%A2%D0%B5%D0%B0%D1%82%D1%80_%D0%B2_%D0%9A%D1%83%D1%80%D0%B8%D0%BE%D0%BD%D0%B5", "url": "https://ru.wikipedia.org/wiki/%D0%A2%D0%B5%D0%B0%D1%82%D1%80_%D0%B2_%D0%9A%D1%83%D1%80%D0%B8%D0%BE%D0%BD%D0%B5", "quote": "Театр в Курионе — античный театр, одна из главных достопримечательностей среди сохранившихся развалин греческого города Курион.", "outcome": "found"}, {"source": "https://www.iccrom.org/resources/resources-of-the-month/cyprus-magnificent-greek-roman-theatre-kourion", "url": "https://www.iccrom.org/resources/resources-of-the-month/cyprus-magnificent-greek-roman-theatre-kourion", "quote": "Kourion was one of the most important ancient city-states on the south-western coast of Cyprus. The majority of Kourion’s archaeological remains date from the Roman and Late Roman/Early Byzantine periods. The theatre - the site’s centrepiece - was built in the 2nd century BCE and was enlarged under Trajan in the 2nd century CE.", "outcome": "found"}, {"source": "https://www.discoverwalks.com/blog/cyprus/top-10-intriguing-facts-about-%CE%BAourion-ancient-amphitheater/", "url": "https://www.discoverwalks.com/blog/cyprus/top-10-intriguing-facts-about-%CE%BAourion-ancient-amphitheater/", "quote": "The area is famous for hosting many ancient structures one of them being Κourion Ancient Amphitheater.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the generic English article Theatre (Q11635), not this site. The site is the ancient theatre of Kourion near Limassol (Wikidata Q4453457, Roman Theatre of Kourion), which has its own Russian Wikipedia article, Театр в Курионе; ICCROM independently describes the Greek-Roman theatre of Kourion as the centrepiece of the site.", "value_page": {"lang": "ru", "problem": null, "resolved_title": "Театр в Курионе", "unreadable": false, "wikibase_item": "Q4453457"}}]'::jsonb),
    ('0c879c8d-da82-4297-be35-796650ca0765'::uuid, 'geom', 'SRID=4326;POINT(-3.4708 51.9417)', '0101000020E610000098E516DFA6EB0BC081B0F478CDF64940', 'fields-wd1-2026-09-26b-s001-rollback:0c879c8d-da82-4297-be35-796650ca0765:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E610000098E516DFA6EB0BC081B0F478CDF64940'' restored on Mynydd Illtud', '[{"source": "https://en.wikipedia.org/wiki/Mynydd_Illtud", "url": "https://en.wikipedia.org/wiki/Mynydd_Illtud", "quote": "51.9417°N 3.4708°W", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4095", "url": "https://www.megalithic.co.uk/article.php?sid=4095", "quote": "Latitude: 51.941303N Longitude: 3.470702W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0155)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point is the middle of Mynydd Illtud common, but the site is the Iron Age hillfort of Twyn y Gaer at the north-east end of the ridge (Cadw BR043A, grid SN990280). English Wikipedia gives Twyn y Gaer at 51.9417 N, 3.4708 W and the Megalithic Portal entry for Twyn-y-Gaer (Llanspyddid), map ref SN990280, gives 51.941303 N, 3.470702 W; both are about 2 km from the stored point and within 0.05 km of each other.", "value_page": null}]'::jsonb),
