    ('0c879c8d-da82-4297-be35-796650ca0765'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s001-rollback:0c879c8d-da82-4297-be35-796650ca0765:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1500 - 500 BC'' restored on Mynydd Illtud', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0c879c8d-da82-4297-be35-796650ca0765'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s001-rollback:0c879c8d-da82-4297-be35-796650ca0765:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-1500'' restored on Mynydd Illtud', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0155)", "decision": "clear", "status": "MISSING", "reasoning": "Only Cadw''s record dates the Twyn y Gaer hillfort (BR043A: probably Iron Age, c. 800 BC - AD 74); Wikipedia, the RCAHMW Coflein record, the Megalithic Portal and the Fforest Fawr Geopark all say just ''Iron Age'' with no date, and no excavation has dated it. Two independent sources do not date the start, so the field is cleared.", "value_page": null}]'::jsonb),
    ('0c879c8d-da82-4297-be35-796650ca0765'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s001-rollback:0c879c8d-da82-4297-be35-796650ca0765:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Fortress/citadel'' restored on Mynydd Illtud', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=801", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=801", "quote": "The monument comprises the remains of a hillfort, which probably dates to the Iron Age period (c. 800 BC - AD 74, the Roman conquest of Wales).", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Mynydd_Illtud", "url": "https://en.wikipedia.org/wiki/Mynydd_Illtud", "quote": "Twyn y Gaer is the site of an Iron Age hill fort", "outcome": "found"}, {"source": "https://www.fforestfawrgeopark.org.uk/enjoying/places-to-go/classic-beacons/mynydd-illtud-and-traeth-mawr/", "url": "https://www.fforestfawrgeopark.org.uk/enjoying/places-to-go/classic-beacons/mynydd-illtud-and-traeth-mawr/", "quote": "An Iron Age hillfort is perched atop Twyn y Gaer at the north end of the common.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0155)", "decision": "replace", "status": "CONFLICT", "reasoning": "Cadw (BR043A Twyn-y-Gaer Hillfort), English Wikipedia and the Fforest Fawr Geopark all describe an Iron Age hillfort on Twyn y Gaer at the north end of Mynydd Illtud; nothing calls it a fortress or citadel, and the hill class of the item is not the site''s type, so the specific canonical type is Fort.", "value_page": null}]'::jsonb),
    ('0d141532-586a-4a6f-bfa0-78186786402e'::uuid, 'geom', 'SRID=4326;POINT(15.99244 41.39704)', '0101000020E6100000BABB1004F3C12F400152379830BC4440', 'fields-wd1-2026-09-26b-s001-rollback:0d141532-586a-4a6f-bfa0-78186786402e:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E6100000BABB1004F3C12F400152379830BC4440'' restored on Salapia', '[{"source": "https://imperium.ahlfeldt.se/places/23207", "url": "https://imperium.ahlfeldt.se/places/23207", "quote": "41.39704, 15.99244", "outcome": "found"}, {"source": "http://nomisma.org/id/salapia", "url": "http://nomisma.org/id/salapia", "quote": "Latitude 41.403381 Longitude 15.993300", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0087)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Digital Atlas of the Roman Empire places Salapia at Salpi (Cerignola) at 41.39704, 15.99244 and Nomisma''s ''ancient site of Salapia'' at 41.403381, 15.9933 - the Monte di Salpi town excavated by the Salapia Exploration Project; the stored point near Zapponeta lies about 12.5 km north-west of it and about 10 km north of Salpia vetus (Lupara-Torretta dei Monaci), so it marks neither.", "value_page": null}]'::jsonb),
