    ('0d2486f1-4650-4c10-9f4c-b25a3e345012'::uuid, 'period_name', '1 - 500 AD', '500 - 1000 AD', 'fields-wd1-2026-09-26b-s001-rollback:0d2486f1-4650-4c10-9f4c-b25a3e345012:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 - 1000 AD'' restored on Nim Li Punit', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(150) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0d2486f1-4650-4c10-9f4c-b25a3e345012'::uuid, 'period_start', '150', '500', 'fields-wd1-2026-09-26b-s001-rollback:0d2486f1-4650-4c10-9f4c-b25a3e345012:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''500'' restored on Nim Li Punit', '[{"source": "https://today.ucsd.edu/story/a_pendant_fit_for_a_king", "url": "https://today.ucsd.edu/story/a_pendant_fit_for_a_king", "quote": "Nim Li Punit is estimated to have been inhabited between A.D. 150 and 850.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Nim_Li_Punit", "url": "https://en.wikipedia.org/wiki/Nim_Li_Punit", "quote": "Nim Li Punit is a medium-sized site from the Maya Classic Period, flourishing from the 5th century AD through the 8th century AD.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0011)", "decision": "replace", "status": "MISSING", "reasoning": "UC San Diego, reporting its excavator Geoffrey Braswell, dates the occupation of Nim Li Punit from A.D. 150, and Wikipedia has the site flourishing from the 5th century AD; both put the start in the 1 - 500 AD bucket, not the stored 500 - 1000 AD, and the attested start is AD 150.", "value_page": null}]'::jsonb),
    ('0d9dc1e0-d65e-4507-be51-4c2220ba8de3'::uuid, 'site_type', 'Fortification', 'Residence/villa/farmhouse', 'fields-wd1-2026-09-26b-s001-rollback:0d9dc1e0-d65e-4507-be51-4c2220ba8de3:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Residence/villa/farmhouse'' restored on Louloudies', '[{"source": "https://en.wikipedia.org/wiki/Louloudies", "url": "https://en.wikipedia.org/wiki/Louloudies", "quote": "It comprises a fortified bishop''s seat from the Byzantine era", "outcome": "found"}, {"source": "https://golden-greece.gr/en/archaeological/makedonia/pieria/episkopiko-sygkrotima-louloudies-kitrous", "url": "https://golden-greece.gr/en/archaeological/makedonia/pieria/episkopiko-sygkrotima-louloudies-kitrous", "quote": "the ruins of a fortified episcopal complex of the 5th-6th c. AD", "outcome": "found"}, {"source": "https://golden-greece.gr/en/archaeological/makedonia/pieria/episkopiko-sygkrotima-louloudies-kitrous", "url": "https://golden-greece.gr/en/archaeological/makedonia/pieria/episkopiko-sygkrotima-louloudies-kitrous", "quote": "Today, the visitor can admire the fortification with three of its towers, the basilica, the episcopal palace", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0067)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Golden Greece describe Louloudies as a fortified episcopal complex: an 80 x 90 m walled enclosure with four corner towers holding a basilica and a bishop''s palace. The bishop''s residence is only one part of it, so ''Residence/villa/farmhouse'' does not fit. No quotable English source gives it a church or religious type word, so Fortification is the most specific type that holds.", "value_page": null}]'::jsonb),
    ('0db1078f-012b-42ef-a9b4-e5e482c92767'::uuid, 'site_type', 'Village', 'Megalithic stones', 'fields-wd1-2026-09-26b-s001-rollback:0db1078f-012b-42ef-a9b4-e5e482c92767:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Megalithic stones'' restored on Orongo', '[{"source": "https://en.wikipedia.org/wiki/Orongo", "url": "https://en.wikipedia.org/wiki/Orongo", "quote": "is a stone village and ceremonial center at the southwestern tip of Rapa Nui (Easter Island).", "outcome": "found"}, {"source": "https://theorangeexplorer.com/stories/rapa-nui-orongo/", "url": "https://theorangeexplorer.com/stories/rapa-nui-orongo/", "quote": "Orongo is a Rapa Nui ceremonial village built on the narrow rim of Rano Kau, between the volcano’s crater and cliffs overlooking the Pacific Ocean.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0016)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia describes Orongo as a stone village and ceremonial centre, and The Orange Explorer as a ceremonial village of 54 stone houses on the rim of Rano Kau. The site is a village of stone houses, not a group of megalithic stones.", "value_page": null}]'::jsonb),
