    ('0dfe2efe-0699-4300-8f2e-04852c23ab55'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s001-rollback:0dfe2efe-0699-4300-8f2e-04852c23ab55:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-4500'' restored on Balls Head Reserve', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, North Sydney Council, the NSW Government page and the Megalithic Portal describe the Aboriginal middens, art sites and engravings of Balls Head but give no date for their start; no source dates the site, so the field is emptied.", "value_page": null}]'::jsonb),
    ('0e004ad3-7c38-4926-8bb7-86593ec4c4f7'::uuid, 'source_url', 'https://fr.wikipedia.org/wiki/Deir_el-Qalaa', 'https://en.wikipedia.org/wiki/Beit_Mery', 'fields-wd1-2026-09-26b-s001-rollback:0e004ad3-7c38-4926-8bb7-86593ec4c4f7:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Beit_Mery'' restored on Deir el kalaa', '[{"source": "https://fr.wikipedia.org/wiki/Deir_el-Qalaa", "url": "https://fr.wikipedia.org/wiki/Deir_el-Qalaa", "quote": "Le site de Deir el-Qalaa est un sanctuaire romain et byzantin", "outcome": "found"}, {"source": "https://www.discoverlebanon.com/en/panoramic_views/mount_lebanon/el_maten/deir_kalaa_beit_mery.php", "url": "https://www.discoverlebanon.com/en/panoramic_views/mount_lebanon/el_maten/deir_kalaa_beit_mery.php", "quote": "The Story of Deir el Kalaa, Monastery of the Citadel", "outcome": "found"}, {"source": "https://culturalheritageonline.com/places/deir-el-qalaa-beit-mery/", "url": "https://culturalheritageonline.com/places/deir-el-qalaa-beit-mery/", "quote": "Deir el-Qalaa — the name means the convent of the citadel — stands at the southern edge of Beit Mery", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0016)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Beit Mery article is about the town (Q2894054); the site''s own article is the French Wikipedia Deir el-Qalaa (Wikidata Q47635498 sitelink), which describes the Roman and Byzantine sanctuary, and Cultural Heritage Online independently describes the same site at the southern edge of Beit Mery.", "value_page": {"lang": "fr", "problem": null, "resolved_title": "Deir el-Qalaa", "unreadable": false, "wikibase_item": "Q47635498"}}]'::jsonb),
    ('0e5f74c4-f35a-4f3b-8875-98c3c91da9fe'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s001-rollback:0e5f74c4-f35a-4f3b-8875-98c3c91da9fe:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1 - 500 AD'' restored on Warahirka', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0e5f74c4-f35a-4f3b-8875-98c3c91da9fe'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s001-rollback:0e5f74c4-f35a-4f3b-8875-98c3c91da9fe:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1'' restored on Warahirka', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0115)", "decision": "clear", "status": "MISSING", "reasoning": "The MINCETUR inventory assigns the site to the Late Intermediate Period and the Yarowilca culture but gives no year or century. No source dates the start, and nothing supports the stored 1 AD, so the field is emptied.", "value_page": null}]'::jsonb),
    ('0e5f74c4-f35a-4f3b-8875-98c3c91da9fe'::uuid, 'site_type', 'Archaeological site', 'City/town/settlement', 'fields-wd1-2026-09-26b-s001-rollback:0e5f74c4-f35a-4f3b-8875-98c3c91da9fe:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''City/town/settlement'' restored on Warahirka', '[{"source": "https://en.wikipedia.org/wiki/Warahirka", "url": "https://en.wikipedia.org/wiki/Warahirka", "quote": "Hispanicized spellings Huarajirca, Huara Jirca) is a mountain with an archaeological site of the same name in Peru.", "outcome": "found"}, {"source": "https://www.turismoperuano.com/sitio-arqueologico-huarajirca-huanuco", "url": "https://www.turismoperuano.com/sitio-arqueologico-huarajirca-huanuco", "quote": "En este sitio arqueológico se encuentra ubicado en la cuchilla del cerro Huara Jirca", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0115)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe only an archaeological site on the ridge of Huara Jirca mountain. The inventory lists a semicircular tower, a small dwelling and a two-storey structure, but no source calls it a town or settlement, so the stored City/town/settlement is replaced by the generic type.", "value_page": null}]'::jsonb),
    ('0e942695-743b-4144-bf9f-f5687fc61447'::uuid, 'site_type', 'Earthwork', 'Archaeological site', 'fields-wd1-2026-09-26b-s001-rollback:0e942695-743b-4144-bf9f-f5687fc61447:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Archaeological site'' restored on Court Hill, Sussex', '[{"source": "https://en.wikipedia.org/wiki/Court_Hill_(West_Sussex)", "url": "https://en.wikipedia.org/wiki/Court_Hill_(West_Sussex)", "quote": "a form of earthwork that was built in northwestern Europe", "outcome": "found"}, {"source": "https://www.cdas.info/PDF/Court%20Hill%20Geophys%202025%20-%20Final%20report.pdf", "url": "https://www.cdas.info/PDF/Court%20Hill%20Geophys%202025%20-%20Final%20report.pdf", "quote": "this is a monument that has earthworks in places, only slight to see", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?mapref=SU906132", "url": "https://www.megalithic.co.uk/article.php?mapref=SU906132", "quote": "Type: Causewayed Enclosure", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0032)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, the CDAS survey report and the Megalithic Portal describe Court Hill as a Neolithic causewayed enclosure, a ditched earthwork enclosure; Earthwork is the most specific canonical type for it, replacing the generic ''Archaeological site''.", "value_page": null}]'::jsonb),
    ('0eaedf34-031e-4b8f-8fff-2db84a3e6da6'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s001-rollback:0eaedf34-031e-4b8f-8fff-2db84a3e6da6:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''4500 - 3000 BC'' restored on Moylehid', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0eaedf34-031e-4b8f-8fff-2db84a3e6da6'::uuid, 'period_start', NULL, '-4000', 'fields-wd1-2026-09-26b-s001-rollback:0eaedf34-031e-4b8f-8fff-2db84a3e6da6:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-4000'' restored on Moylehid', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0101)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia says only that the two cairns contain evidence of Neolithic settlement, and a local walk blog says late Neolithic to Early Bronze Age; no source gives a year, century or millennium for the start, so the stored 4000 BC is unattested and cleared.", "value_page": null}]'::jsonb),
    ('0eaedf34-031e-4b8f-8fff-2db84a3e6da6'::uuid, 'source_url', 'https://megalithicarchaeoastronomy.blogspot.com/p/moylehid.html', 'https://en.wikipedia.org/wiki/Moylehid', 'fields-wd1-2026-09-26b-s001-rollback:0eaedf34-031e-4b8f-8fff-2db84a3e6da6:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Moylehid'' restored on Moylehid', '[{"source": "https://megalithicarchaeoastronomy.blogspot.com/p/moylehid.html", "url": "https://megalithicarchaeoastronomy.blogspot.com/p/moylehid.html", "quote": "Moylehid Suspected Alignment / Alignments", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Moylehid", "url": "https://en.wikipedia.org/wiki/Moylehid", "quote": "These are the Eagle''s Knoll Cairn passage tomb and the Moylehid ring cairn.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0101)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the townland. No Wikipedia article on the cairn exists, and the NI Sites and Monuments Record needs a session. This page is about the Moylehid passage tomb itself (grid H14994161, the scheduled Eagle''s Knoll cairn) and quotes the official NI record and Coffey''s excavation report.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('0ec71a0c-1f82-4890-a9a8-8238461f9bc0'::uuid, 'site_type', 'Earthwork', 'City/town/settlement', 'fields-wd1-2026-09-26b-s001-rollback:0ec71a0c-1f82-4890-a9a8-8238461f9bc0:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''City/town/settlement'' restored on Llanos de Moxos (archaeology)', '[{"source": "https://en.wikipedia.org/wiki/Llanos_de_Moxos_(archaeology)", "url": "https://en.wikipedia.org/wiki/Llanos_de_Moxos_(archaeology)", "quote": "A variety of earthworks have been identified throughout the Llanos de Moxos.", "outcome": "found"}, {"source": "https://www.penn.museum/sites/expedition/hidden-earthworks-in-the-forests-of-the-bolivian-amazon/", "url": "https://www.penn.museum/sites/expedition/hidden-earthworks-in-the-forests-of-the-bolivian-amazon/", "quote": "In Mojos and across southern Amazonia, circular ring ditches are the predominant form of pre-Columbian earthworks.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0012)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and John Walker''s Penn Museum Expedition article describe the Llanos de Moxos (Mojos) site as a landscape of pre-Columbian earthworks (mounds, raised fields, canals, causeways, ring ditches, fish weirs), not as one city or town, so Earthwork replaces City/town/settlement.", "value_page": null}]'::jsonb),
    ('0ecacadb-c9da-490b-95ef-4b220c386d3d'::uuid, 'geom', 'SRID=4326;POINT(-3.955556 40.188889)', '0101000020E6100000C797F78FBE2C0FC0B302756EE2154440', 'fields-wd1-2026-09-26b-s001-rollback:0ecacadb-c9da-490b-95ef-4b220c386d3d:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E6100000C797F78FBE2C0FC0B302756EE2154440'' restored on Carranque', '[{"source": "https://www.wikidata.org/wiki/Q766555", "url": "https://www.wikidata.org/wiki/Q766555", "quote": "40°11''20\"N, 3°57''20\"W", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=40465", "url": "https://www.megalithic.co.uk/article.php?sid=40465", "quote": "Latitude: 40.186245N Longitude: 3.957533W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0129)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the Roman villa of Santa María de Abajo (Carranque Archaeological Park), 5.3 km north-west of the town; its Wikidata item places it at 40.188889, -3.955556 and the Megalithic Portal at 40.186245, -3.957533, while the stored point is the town centre, so it is replaced.", "value_page": null}]'::jsonb),
