    ('0ecacadb-c9da-490b-95ef-4b220c386d3d'::uuid, 'site_type', 'Villa', 'Residence/villa/farmhouse', 'fields-wd1-2026-09-26b-s001-rollback:0ecacadb-c9da-490b-95ef-4b220c386d3d:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Residence/villa/farmhouse'' restored on Carranque', '[{"source": "https://es.wikipedia.org/wiki/Villa_romana_de_Carranque", "url": "https://es.wikipedia.org/wiki/Villa_romana_de_Carranque", "quote": "La villa romana de Carranque es una villa romana situada en el municipio español de", "outcome": "found"}, {"source": "https://www.radiosapiens.es/la-casa-de-materno-cabeza-de-un-gran-dominio-agropecuario-de-la-hispania-tardorromana/", "url": "https://www.radiosapiens.es/la-casa-de-materno-cabeza-de-un-gran-dominio-agropecuario-de-la-hispania-tardorromana/", "quote": "Al frente de esta villa se encontraba Materno", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0129)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Radio Sapiens describe the site as a Roman villa (the villa of Maternus, later with a late-Roman palatial building); Villa is the most specific canonical type.", "value_page": null}]'::jsonb),
    ('0ecacadb-c9da-490b-95ef-4b220c386d3d'::uuid, 'source_url', 'https://es.wikipedia.org/wiki/Villa_romana_de_Carranque', 'https://en.wikipedia.org/wiki/Carranque', 'fields-wd1-2026-09-26b-s001-rollback:0ecacadb-c9da-490b-95ef-4b220c386d3d:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Carranque'' restored on Carranque', '[{"source": "https://es.wikipedia.org/wiki/Villa_romana_de_Carranque", "url": "https://es.wikipedia.org/wiki/Villa_romana_de_Carranque", "quote": "La villa romana de Carranque es una villa romana situada en el municipio español de", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=40465", "url": "https://www.megalithic.co.uk/article.php?sid=40465", "quote": "Site Name: Yacimiento Romano de Carranque", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0129)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the municipality; Spanish Wikipedia has an article on the Roman villa itself, which the Megalithic Portal records as the Yacimiento Romano de Carranque, so it replaces the stored URL.", "value_page": {"lang": "es", "problem": null, "resolved_title": "Villa romana de Carranque", "unreadable": false, "wikibase_item": "Q766555"}}]'::jsonb),
    ('0ed41363-8709-42cc-a676-7cb76e3440bf'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s001-rollback:0ed41363-8709-42cc-a676-7cb76e3440bf:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1500 - 500 BC'' restored on Mitla, Entrance to Tomb 1', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0ed41363-8709-42cc-a676-7cb76e3440bf'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s001-rollback:0ed41363-8709-42cc-a676-7cb76e3440bf:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-1500'' restored on Mitla, Entrance to Tomb 1', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0096)", "decision": "clear", "status": "MISSING", "reasoning": "Arqueología Mexicana dates Mitla''s cruciform tombs only broadly to the Late Classic-Early Postclassic, with tomb 3 probably the first (c. 850 AD) and patio F of the Group of the Columns used from the Early Postclassic; no source gives a year for Tomb 1, and the stored 1500 BC is far older than any occupation of Mitla.", "value_page": null}]'::jsonb),
    ('0ed41363-8709-42cc-a676-7cb76e3440bf'::uuid, 'site_type', 'Tomb', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s001-rollback:0ed41363-8709-42cc-a676-7cb76e3440bf:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Necropolis/tombs complex'' restored on Mitla, Entrance to Tomb 1', '[{"source": "https://en.wikipedia.org/wiki/Mitla", "url": "https://en.wikipedia.org/wiki/Mitla", "quote": "In front of the stairs of the north building is a cross-shaped tomb with an antechamber.", "outcome": "found"}, {"source": "https://arqueologiamexicana.mx/mexico-antiguo/las-tumbas-de-mitla-y-los-estudios-de-batres", "url": "https://arqueologiamexicana.mx/mexico-antiguo/las-tumbas-de-mitla-y-los-estudios-de-batres", "quote": "Las tumbas 1 y 3 cruciformes pertenecen a esta variante", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=23446", "url": "https://www.megalithic.co.uk/article.php?sid=23446", "quote": "Entrance to Tomb 1", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0096)", "decision": "replace", "status": "MISSING", "reasoning": "The entry is a single monument, Mitla''s cruciform Tomb 1 (Arqueología Mexicana''s tomb 1, with south entrance and monolithic column; Wikipedia''s cross-shaped tomb of the Group of the Columns), so the type is Tomb, not a necropolis.", "value_page": null}]'::jsonb),
    ('0ed79845-f651-4c52-85cd-7f96bab43d4e'::uuid, 'site_type', 'Standing stone', 'Megalithic stones', 'fields-wd1-2026-09-26b-s001-rollback:0ed79845-f651-4c52-85cd-7f96bab43d4e:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Megalithic stones'' restored on Eightercua Stone Row', '[{"source": "https://www.discoverireland.ie/kerry/eightercua-stone-row", "url": "https://www.discoverireland.ie/kerry/eightercua-stone-row", "quote": "Eightercua Stone Row, just south of Waterville Village in County Kerry, is an impressive standing stone alignment", "outcome": "found"}, {"source": "https://voicesfromthedawn.com/eightercua-alignment/", "url": "https://voicesfromthedawn.com/eightercua-alignment/", "quote": "One of the standing stones showed evidence of an attempt to quarry it for another use.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0082)", "decision": "replace", "status": "CONFLICT", "reasoning": "Discover Ireland and Voices from the Dawn describe Eightercua as an alignment (row) of four standing stones; the tomb is only a possible adjacent feature, so the most specific canonical type is Standing stone rather than the generic Megalithic stones or Wikidata''s Tomb.", "value_page": null}]'::jsonb),
    ('0f1ec894-b1b1-40e9-9e00-bd193b316484'::uuid, 'period_name', NULL, '500 - 1000 AD', 'fields-wd1-2026-09-26b-s001-rollback:0f1ec894-b1b1-40e9-9e00-bd193b316484:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 - 1000 AD'' restored on Kulubá', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0f1ec894-b1b1-40e9-9e00-bd193b316484'::uuid, 'period_start', NULL, '500', 'fields-wd1-2026-09-26b-s001-rollback:0f1ec894-b1b1-40e9-9e00-bd193b316484:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''500'' restored on Kulubá', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0096)", "decision": "clear", "status": "MISSING", "reasoning": "The earliest occupation of Kulubá is placed only in the Late Preclassic, without a year or century (INAH''s Ventana Arqueológica: a first moment ''durante el Preclásico tardío y el Clásico temprano''; the Mayan Ruins Website: ceramics from the end of the Late Preclassic, no structures), while the 600 CE dates belong to the later palaces; no start year is securely attested and the stored 500-1000 AD bucket postdates the first occupation.", "value_page": null}]'::jsonb),
    ('0f43e795-0348-4bfd-bfea-386ab6e59b68'::uuid, 'period_name', NULL, '< 4500 BC', 'fields-wd1-2026-09-26b-s001-rollback:0f43e795-0348-4bfd-bfea-386ab6e59b68:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''< 4500 BC'' restored on Wolf Cave', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0f43e795-0348-4bfd-bfea-386ab6e59b68'::uuid, 'period_start', NULL, '-130000', 'fields-wd1-2026-09-26b-s001-rollback:0f43e795-0348-4bfd-bfea-386ab6e59b68:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-130000'' restored on Wolf Cave', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0050)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia calls the Palaeolithic occupation a speculation resting on objects that may not be artefacts, and the Finnish Heritage Agency register gives it only as ''about 115-130,000 years ago'' (Eemian) and ''Stone Age, undefined''; no source states a year or century for a securely attested start, so the stored -130000 is emptied.", "value_page": null}]'::jsonb),
    ('0f43e795-0348-4bfd-bfea-386ab6e59b68'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Susiluola_Cave', 'https://en.wikipedia.org/wiki/Wolf_Cave', 'fields-wd1-2026-09-26b-s001-rollback:0f43e795-0348-4bfd-bfea-386ab6e59b68:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Wolf_Cave'' restored on Wolf Cave', '[{"source": "https://en.wikipedia.org/wiki/Susiluola_Cave", "url": "https://en.wikipedia.org/wiki/Susiluola_Cave", "quote": "Susiluola (Swedish: Varggrottan, ''Wolf Cave'') is a crack in the Pyhävuori hill (Swedish: Bötombergen) at the border of Kristinestad and Karijoki municipalities in Finland.", "outcome": "found"}, {"source": "https://www.kyppi.fi/palveluikkuna/mjreki/read/asp/r_kohde_det.aspx?KOHDE_ID=409010050", "url": "https://www.kyppi.fi/palveluikkuna/mjreki/read/asp/r_kohde_det.aspx?KOHDE_ID=409010050", "quote": "Kristiinankaupungin Susivuoren pohjoisosassa sijaitsevassa Susiluolassa on merkkejä ihmisen oleskelusta alueella jo ennen viimeisintä jääkautta", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0050)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL Wolf_Cave is a redirect; the article''s own URL is Susiluola_Cave, which is about this cave in Kristinestad, as is the Finnish Heritage Agency register entry Karijoen Susiluola.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Susiluola Cave", "unreadable": false, "wikibase_item": "Q2298812"}}]'::jsonb),
    ('0f654bf4-86b7-4602-8bee-c8da00f3edee'::uuid, 'site_type', 'Temple', 'Temple complex', 'fields-wd1-2026-09-26b-s001-rollback:0f654bf4-86b7-4602-8bee-c8da00f3edee:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Temple complex'' restored on Roman Temple Qsarnaba', '[{"source": "https://www.livius.org/articles/place/qsarnaba/", "url": "https://www.livius.org/articles/place/qsarnaba/", "quote": "Qsarnaba: village in the Bekaa valley in Lebanon, site of a Roman temple.", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Qsarnaba", "url": "https://de.wikipedia.org/wiki/Qsarnaba", "quote": "In der Ortsmitte liegen die mäßig gut erhaltenen Reste eines römischen Tempels", "outcome": "found"}, {"source": "https://books.openedition.org/ifpo/1456", "url": "https://books.openedition.org/ifpo/1456", "quote": "Le temple s’élève sur un massif de fondation rectangulaire de plus de 35 m de long et d’environ 15 m de large.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0092)", "decision": "replace", "status": "MISSING", "reasoning": "Livius, German Wikipedia and Aliquot''s Ifpo catalogue describe a single Roman temple (hexastyle prostyle, on a podium facing a monumental altar) in the village centre; no source describes several temples, so Temple replaces Temple complex.", "value_page": null}]'::jsonb),
    ('0f7ccb2e-da01-425e-9a4b-c50f4a785065'::uuid, 'source_url', 'https://hr.wikipedia.org/wiki/Amfiteatar_u_Saloni', 'https://en.wikipedia.org/wiki/Theatre', 'fields-wd1-2026-09-26b-s001-rollback:0f7ccb2e-da01-425e-9a4b-c50f4a785065:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Theatre'' restored on Amfiteatar Salona', '[{"source": "https://hr.wikipedia.org/wiki/Amfiteatar_u_Saloni", "url": "https://hr.wikipedia.org/wiki/Amfiteatar_u_Saloni", "quote": "Amfiteatar u Saloni izgrađen je u drugoj polovici 2. stoljeća za vladavine cara Marka Aurelija", "outcome": "found"}, {"source": "https://solin-info.com/en/znamenitosti/znamenitosti/amfiteatar", "url": "https://solin-info.com/en/znamenitosti/znamenitosti/amfiteatar", "quote": "At the northwest end of Salona’s town limits, subsequently fortified, there is an amphitheatre, which forms part of the town defence system.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0016)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the generic English article on theatres. The amphitheatre has no English article; its own Wikipedia article is Croatian (Amfiteatar u Saloni), linked from its Wikidata item Q2844418. The Solin tourist board describes the same amphitheatre at the north-west end of Salona.", "value_page": {"lang": "hr", "problem": null, "resolved_title": "Amfiteatar u Saloni", "unreadable": false, "wikibase_item": "Q2844418"}}]'::jsonb),
    ('0fb3b6cd-57cc-4ed6-b4a3-97a580cadfcc'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s001-rollback:0fb3b6cd-57cc-4ed6-b4a3-97a580cadfcc:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1 - 500 AD'' restored on Roman Villa of Ammaia', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-100) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0fb3b6cd-57cc-4ed6-b4a3-97a580cadfcc'::uuid, 'period_start', '-100', '1', 'fields-wd1-2026-09-26b-s001-rollback:0fb3b6cd-57cc-4ed6-b4a3-97a580cadfcc:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1'' restored on Roman Villa of Ammaia', '[{"source": "https://arqueologia.patrimoniocultural.pt/index.php/?sid=visitaveis&subsid=48078&lang=en", "url": "https://arqueologia.patrimoniocultural.pt/index.php/?sid=visitaveis&subsid=48078&lang=en", "quote": "chronologically framed between the end of the 1st-century BC and the end of the 5th century AD.", "outcome": "found"}, {"source": "https://imperiumromanum.pl/en/roman-geography/roman-cities/ammaia/", "url": "https://imperiumromanum.pl/en/roman-geography/roman-cities/ammaia/", "quote": "Ammaia is a Roman city in central-eastern Portugal (near Marvao), which was founded at the end of the 1st century BCE.", "outcome": "found"}, {"source": "https://pt.wikipedia.org/wiki/Ammaia", "url": "https://pt.wikipedia.org/wiki/Ammaia", "quote": "A povoação foi fundada provavelmente nos finais do século I a.C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0021)", "decision": "replace", "status": "MISSING", "reasoning": "The national archaeology portal frames the Roman city of Ammaia (Sao Salvador da Aramenha, Marvao) from the end of the 1st century BC, Imperium Romanum says it was founded at the end of the 1st century BCE, and the Portuguese Wikipedia says it was probably founded in the late 1st century BC under Augustus. The start therefore lies in the 1st century BC, in the bucket 500 BC - 1 AD, not the stored 1 - 500 AD (the later civitas status of 44-45 AD is not the foundation).", "value_page": null}]'::jsonb),
    ('0fb3b6cd-57cc-4ed6-b4a3-97a580cadfcc'::uuid, 'site_type', 'City', 'Residence/villa/farmhouse', 'fields-wd1-2026-09-26b-s001-rollback:0fb3b6cd-57cc-4ed6-b4a3-97a580cadfcc:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Residence/villa/farmhouse'' restored on Roman Villa of Ammaia', '[{"source": "https://arqueologia.patrimoniocultural.pt/index.php/?sid=visitaveis&subsid=48078&lang=en", "url": "https://arqueologia.patrimoniocultural.pt/index.php/?sid=visitaveis&subsid=48078&lang=en", "quote": "The archaeological interventions identified structural and artefactual traces of a Roman city", "outcome": "found"}, {"source": "https://imperiumromanum.pl/en/roman-geography/roman-cities/ammaia/", "url": "https://imperiumromanum.pl/en/roman-geography/roman-cities/ammaia/", "quote": "Ammaia is a Roman city in central-eastern Portugal (near Marvao), which was founded at the end of the 1st century BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0021)", "decision": "replace", "status": "CONFLICT", "reasoning": "The national archaeology portal and Imperium Romanum both describe Ammaia (Marvao, Portugal) as a Roman city with a forum, baths and south gate, not a villa; the stored type Residence/villa/farmhouse is wrong and City is the most specific canonical type.", "value_page": null}]'::jsonb),
    ('0fc7924f-75ff-4965-98b5-ba35856b57ea'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Ed-Deir,_Petra', 'https://en.wikipedia.org/wiki/Ad_Deir', 'fields-wd1-2026-09-26b-s001-rollback:0fc7924f-75ff-4965-98b5-ba35856b57ea:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Ad_Deir'' restored on Ad-Deir', '[{"source": "https://en.wikipedia.org/wiki/Ed-Deir,_Petra", "url": "https://en.wikipedia.org/wiki/Ed-Deir,_Petra", "quote": "also spelled el-Deir and ad-Deir/ad-Dayr", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Ed-Deir,_Petra", "url": "https://en.wikipedia.org/wiki/Ed-Deir,_Petra", "quote": "The Deir was probably carved in the mid-first century AD.", "outcome": "found"}, {"source": "http://www.art-and-archaeology.com/jordan/petra/deir/de04.html", "url": "http://www.art-and-archaeology.com/jordan/petra/deir/de04.html", "quote": "ad-Deir (Monastery)", "outcome": "found"}, {"source": "http://www.art-and-archaeology.com/jordan/petra/deir/de04.html", "url": "http://www.art-and-archaeology.com/jordan/petra/deir/de04.html", "quote": "Located high in the mountains to the northwest of the city, the Deir is thought to have been carved in the mid-first century AD (Taylor, p. 98).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0090)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL ''Ad_Deir'' is a redirect; the article itself is ''Ed-Deir, Petra'', about this monument, and Old Stones describes the same Deir at Petra.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Ed-Deir, Petra", "unreadable": false, "wikibase_item": "Q345467"}}]'::jsonb),
    ('105d50fa-5e1b-487e-af70-ff4f6224cd50'::uuid, 'geom', 'SRID=4326;POINT(29.235998 36.717015)', '0101000020E610000018CA57F3E31D3D40A88B29D6D94F4240', 'fields-wd1-2026-09-26b-s001-rollback:105d50fa-5e1b-487e-af70-ff4f6224cd50:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E610000018CA57F3E31D3D40A88B29D6D94F4240'' restored on Kadyanda', '[{"source": "https://en.wikipedia.org/wiki/Cadyanda", "url": "https://en.wikipedia.org/wiki/Cadyanda", "quote": "36°43′01″N 29°14′10″E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=19538", "url": "https://www.megalithic.co.uk/article.php?sid=19538", "quote": "Latitude: 36.712300N Longitude: 29.230600E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0144)", "decision": "replace", "status": "CONFLICT", "reasoning": "Kadyanda lies on a hilltop above Üzümlü, about 24 km north-east of Fethiye; Wikipedia and the Megalithic Portal place its ruins at 36.71-36.72, 29.23-29.24. The stored point, 14.7 km away near Fethiye, is not the site, so it is replaced with the sourced point.", "value_page": null}]'::jsonb),
