    ('105d50fa-5e1b-487e-af70-ff4f6224cd50'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s001-rollback:105d50fa-5e1b-487e-af70-ff4f6224cd50:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1500 - 500 BC'' restored on Kadyanda', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('105d50fa-5e1b-487e-af70-ff4f6224cd50'::uuid, 'period_start', '-500', '-1500', 'fields-wd1-2026-09-26b-s001-rollback:105d50fa-5e1b-487e-af70-ff4f6224cd50:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-1500'' restored on Kadyanda', '[{"source": "https://en.wikipedia.org/wiki/Cadyanda", "url": "https://en.wikipedia.org/wiki/Cadyanda", "quote": "However, the oldest remains of the ancient city that have survived on the surface do not go [back] more than [to] the 5th century BC.", "outcome": "found"}, {"source": "https://www.lycianmonuments.com/kadyanda/", "url": "https://www.lycianmonuments.com/kadyanda/", "quote": "Although there are monumental tombs dating to the 5th century BCE from the dynastic period, the majority of the ruins spread across the hill date to the Roman period.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0144)", "decision": "replace", "status": "MISSING", "reasoning": "An older origin around 3000 BC is only inferred from the name''s suffix; the oldest surviving remains of Kadyanda, its walls and dynastic tombs, date to the 5th century BC (Wikipedia, Lycian Monuments). The attested start is therefore 500 BC, in the 500 BC - 1 AD bucket rather than 1500 - 500 BC.", "value_page": null}]'::jsonb),
    ('105d50fa-5e1b-487e-af70-ff4f6224cd50'::uuid, 'site_type', 'City', 'Temple complex', 'fields-wd1-2026-09-26b-s001-rollback:105d50fa-5e1b-487e-af70-ff4f6224cd50:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Temple complex'' restored on Kadyanda', '[{"source": "https://en.wikipedia.org/wiki/Cadyanda", "url": "https://en.wikipedia.org/wiki/Cadyanda", "quote": "The ancient city of Cadianda is located [at] about 24 km. distance from Fethiye.", "outcome": "found"}, {"source": "https://www.lycianmonuments.com/kadyanda/", "url": "https://www.lycianmonuments.com/kadyanda/", "quote": "The city is located on a hill to the south of the town of Üzümlü in the Fethiye district of Muğla.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0144)", "decision": "replace", "status": "CONFLICT", "reasoning": "Kadyanda is a Lycian city with walls, theatre, stadium, agora, baths and temples; Wikipedia and Lycian Monuments describe it as an ancient city, not a temple complex, so the type is City.", "value_page": null}]'::jsonb),
