    ('109fcdea-c114-4143-87ac-77c4c9c20f16'::uuid, 'period_name', '< 4500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s001-rollback:109fcdea-c114-4143-87ac-77c4c9c20f16:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''3000 - 1500 BC'' restored on Hattusas', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-6000) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('109fcdea-c114-4143-87ac-77c4c9c20f16'::uuid, 'period_start', '-6000', '-3000', 'fields-wd1-2026-09-26b-s001-rollback:109fcdea-c114-4143-87ac-77c4c9c20f16:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-3000'' restored on Hattusas', '[{"source": "https://en.wikipedia.org/wiki/Hattusa", "url": "https://en.wikipedia.org/wiki/Hattusa", "quote": "The earliest traces of settlement on the site are from the 6th millennium BC during the Chalcolithic period.", "outcome": "found"}, {"source": "https://placesofpeace.eu/theroute/hattusa-archaeological-site/", "url": "https://placesofpeace.eu/theroute/hattusa-archaeological-site/", "quote": "Archaeological excavations have demonstrated that the earliest settlement at the site dates back well before the Hittite period, to the Chalcolithic Age in the 6th millennium BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0144)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia and the Places of Peace route both state that the first settlement on the site of Hattusa dates to the Chalcolithic 6th millennium BC, long before the Hattian town of the late 3rd millennium; the start therefore lies in the < 4500 BC bucket, not 3000 - 1500 BC.", "value_page": null}]'::jsonb),
    ('109fcdea-c114-4143-87ac-77c4c9c20f16'::uuid, 'site_type', 'City', 'City/town/settlement', 'fields-wd1-2026-09-26b-s001-rollback:109fcdea-c114-4143-87ac-77c4c9c20f16:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''City/town/settlement'' restored on Hattusas', '[{"source": "https://en.wikipedia.org/wiki/Hattusa", "url": "https://en.wikipedia.org/wiki/Hattusa", "quote": "A carbonized layer apparent in excavations attests to the burning and ruin of the city of Hattusa around 1700 BC.", "outcome": "found"}, {"source": "https://placesofpeace.eu/theroute/hattusa-archaeological-site/", "url": "https://placesofpeace.eu/theroute/hattusa-archaeological-site/", "quote": "With only brief interruptions, the city served as the capital from approximately 1650 BCE until 1200 BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0144)", "decision": "replace", "status": "MISSING", "reasoning": "Hattusa was the capital city of the Hittite Empire; both sources describe it as a city, so the most specific canonical type is City rather than the broader City/town/settlement.", "value_page": null}]'::jsonb),
    ('111a0de2-2005-43a9-947f-c5d1bddda27d'::uuid, 'site_type', 'Archaeological site', 'Museum', 'fields-wd1-2026-09-26b-s001-rollback:111a0de2-2005-43a9-947f-c5d1bddda27d:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Museum'' restored on Schöningen Spears', '[{"source": "https://en.wikipedia.org/wiki/Sch%C3%B6ningen_site", "url": "https://en.wikipedia.org/wiki/Sch%C3%B6ningen_site", "quote": "The Schöningen site is an archaeological site at a mine in Lower Saxony, in Germany that has yielded significant Paleolithic artifacts dating to approximately 300,000 years ago.", "outcome": "found"}, {"source": "https://www.tu-braunschweig.de/en/igeo/research/schoeningen", "url": "https://www.tu-braunschweig.de/en/igeo/research/schoeningen", "quote": "The archaeological site in the open-cast lignite mine of Schöningen is one of the most important Lower Palaeolithic localities in central Europe.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0059)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the Palaeolithic find site in the Schöningen lignite mine, not the museum that displays the spears; Wikipedia and TU Braunschweig both describe it as an archaeological site, and no more specific canonical type fits an open-air lakeshore hunting site.", "value_page": null}]'::jsonb),
    ('111a0de2-2005-43a9-947f-c5d1bddda27d'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Sch%C3%B6ningen_site', 'https://en.wikipedia.org/wiki/Sch%C3%B6ningen_spears', 'fields-wd1-2026-09-26b-s001-rollback:111a0de2-2005-43a9-947f-c5d1bddda27d:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Sch%C3%B6ningen_spears'' restored on Schöningen Spears', '[{"source": "https://en.wikipedia.org/wiki/Sch%C3%B6ningen_site", "url": "https://en.wikipedia.org/wiki/Sch%C3%B6ningen_site", "quote": "The Schöningen site is an archaeological site at a mine in Lower Saxony, in Germany that has yielded significant Paleolithic artifacts dating to approximately 300,000 years ago.", "outcome": "found"}, {"source": "https://www.tu-braunschweig.de/en/igeo/research/schoeningen", "url": "https://www.tu-braunschweig.de/en/igeo/research/schoeningen", "quote": "The archaeological site in the open-cast lignite mine of Schöningen is one of the most important Lower Palaeolithic localities in central Europe.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0059)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the spears as artefacts; English Wikipedia has its own article on the Schöningen site where they were found, and TU Braunschweig''s research page describes that same site.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Schöningen site", "unreadable": false, "wikibase_item": "Q90926725"}}]'::jsonb),
    ('11aae1cf-691a-45a5-a873-e4ac938587b2'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s001-rollback:11aae1cf-691a-45a5-a873-e4ac938587b2:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 BC - 1 AD'' restored on Öküzlü Ören Yeri', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('11aae1cf-691a-45a5-a873-e4ac938587b2'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s001-rollback:11aae1cf-691a-45a5-a873-e4ac938587b2:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-500'' restored on Öküzlü Ören Yeri', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0148)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and the Mersin University survey (surveymersin.mersin.edu.tr) both trace the settlement back to the Hellenistic period, from its polygonal masonry, but neither gives a year or century for its start. The dated items are later: Roman sarcophagi from the 2nd century AD on and the basilica of c. 500. With no source stating a year or century for the start, the field is emptied.", "value_page": null}]'::jsonb),
    ('11aae1cf-691a-45a5-a873-e4ac938587b2'::uuid, 'site_type', 'Settlement', 'Temple complex', 'fields-wd1-2026-09-26b-s001-rollback:11aae1cf-691a-45a5-a873-e4ac938587b2:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Temple complex'' restored on Öküzlü Ören Yeri', '[{"source": "https://aroundus.com/p/9665514-okuzlu-ruins", "url": "https://aroundus.com/p/9665514-okuzlu-ruins", "quote": "The settlement began in the Hellenistic period and flourished during the early Byzantine era in the 5th and 6th centuries.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/%C3%96k%C3%BCzl%C3%BC", "url": "https://en.wikipedia.org/wiki/%C3%96k%C3%BCzl%C3%BC", "quote": "Öküzlü is an archaeological site in Mersin Province", "outcome": "found"}, {"source": "https://surveymersin.mersin.edu.tr/page7.html", "url": "https://surveymersin.mersin.edu.tr/page7.html", "quote": "Mersin iline bağlı Erdemli ilçesi sınırları içerisindeki Öküzlü antik yerleşimi, Dağlık Kilikia bölgesinde Elaiussa Sebaste’nin khorasında yer almaktadır", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0148)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia''s infobox gives Öküzlü the type Settlement (houses, sarcophagi, a paved road and two churches), and AroundUs calls it a settlement. The Mersin University survey calls it an ancient rural settlement (''antik yerleşim'', a Late Antique village) in the chora of Elaiussa Sebaste. No source describes a temple complex.", "value_page": null}]'::jsonb),
    ('11aae1cf-691a-45a5-a873-e4ac938587b2'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/%C3%96k%C3%BCzl%C3%BC', 'https://www.neredekal.com/okuzlu-oren-yeri-gezilecek-yer-detay/', 'fields-wd1-2026-09-26b-s001-rollback:11aae1cf-691a-45a5-a873-e4ac938587b2:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://www.neredekal.com/okuzlu-oren-yeri-gezilecek-yer-detay/'' restored on Öküzlü Ören Yeri', '[{"source": "https://en.wikipedia.org/wiki/%C3%96k%C3%BCzl%C3%BC", "url": "https://en.wikipedia.org/wiki/%C3%96k%C3%BCzl%C3%BC", "quote": "Öküzlü is an archaeological site in Mersin Province", "outcome": "found"}, {"source": "https://surveymersin.mersin.edu.tr/page7.html", "url": "https://surveymersin.mersin.edu.tr/page7.html", "quote": "Yerleşimde, çok sayıda arkeolojik kalıntı tespit edilmiştir ve bunlar Öküzlü’nün Hellenistik Dönemden gelen, Roma ve Geç Antik Dönemde devam eden kırsal karakterine işaret eder.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0148)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored neredekal.com page is dead (404). The site has its own English Wikipedia article, Öküzlü (the ruins near Batısandal, Erdemli, Mersin), and the Mersin University survey page is also about this site.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Öküzlü", "unreadable": false, "wikibase_item": "Q15437964"}}]'::jsonb),
    ('11ac5108-ad13-4b42-babc-ed1e298bebe3'::uuid, 'source_url', 'https://es.wikipedia.org/wiki/Templo_del_Sol_(Ollantaytambo)', 'https://study.com/academy/lesson/temple-of-the-sun-at-machu-picchu-history-facts.html#:~:text=The%20Temple%20of%20the%20Sun%20is%20an%20ancient%20Inca%20temple,ranking%20Incas%20were%20allowed%20inside.', 'fields-wd1-2026-09-26b-s001-rollback:11ac5108-ad13-4b42-babc-ed1e298bebe3:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://study.com/academy/lesson/temple-of-the-sun-at-machu-picchu-history-facts.html#:~:text=The%20Temple%20of%20the%20Sun%20is%20an%20ancient%20Inca%20temple,ranking%20Incas%20were%20allowed%20inside.'' restored on Templo del Sol', '[{"source": "https://es.wikipedia.org/wiki/Templo_del_Sol_(Ollantaytambo)", "url": "https://es.wikipedia.org/wiki/Templo_del_Sol_(Ollantaytambo)", "quote": "El templo del sol se ubica a 80 km al noreste de la ciudad del Cusco y a 40 km de Machu Picchu, en el distrito de Ollantaytambo, Perú, a una altitud de 2.792 metros (9.160 pies) sobre el nivel del mar.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=23421", "url": "https://www.megalithic.co.uk/article.php?sid=23421", "quote": "These include the Temple of the Sun complex with six massive rose colored rhyolite slabs joined with thinner stone panels between them.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0115)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored study.com link is a text-fragment URL, answers 403, and is about the Temple of the Sun at Machu Picchu, a different site. The site''s own article is the Spanish Wikipedia article on the Ollantaytambo Temple of the Sun (there is no English one); the Megalithic Portal names the same temple independently.", "value_page": {"lang": "es", "problem": null, "resolved_title": "Templo del Sol (Ollantaytambo)", "unreadable": false, "wikibase_item": "Q48785045"}}]'::jsonb),
    ('11d5d105-4613-4bd5-9e52-b17ce6a5c87d'::uuid, 'site_type', 'Cave Structures', 'Temple complex', 'fields-wd1-2026-09-26b-s001-rollback:11d5d105-4613-4bd5-9e52-b17ce6a5c87d:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Temple complex'' restored on Bhaja Caves', '[{"source": "https://maharashtratourism.gov.in/cave/bhaja/", "url": "https://maharashtratourism.gov.in/cave/bhaja/", "quote": "The Bhaja Caves, dating back to the 2nd century BCE, consist of 22 rock-cut caves carved into the rugged hills of Maharashtra.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Bhaja_Caves", "url": "https://en.wikipedia.org/wiki/Bhaja_Caves", "quote": "rock-cut caves dating back to the 2nd century BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0078)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe Bhaja as a group of 22 man-made rock-cut Buddhist caves (a chaitya hall and viharas) cut into a hillside, which is what the canonical type Cave Structures names; Temple complex misstates a group of rock-cut monastic caves.", "value_page": null}]'::jsonb),
    ('1328e959-ddab-4dd5-bc24-071540a6ce0d'::uuid, 'site_type', 'Temple', 'Temple complex', 'fields-wd1-2026-09-26b-s001-rollback:1328e959-ddab-4dd5-bc24-071540a6ce0d:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Temple complex'' restored on Wicklewood Roman Temple', '[{"source": "https://en.wikipedia.org/wiki/Wicklewood_Roman_Temple", "url": "https://en.wikipedia.org/wiki/Wicklewood_Roman_Temple", "quote": "Wicklewood Roman Temple is the site of a Romano-Celtic temple near Wicklewood and about 1.5 miles (2.4 km) north-west of Wymondham, in Norfolk, England.", "outcome": "found"}, {"source": "https://www.heritage.norfolk.gov.uk/record-details?MNF63260", "url": "https://www.heritage.norfolk.gov.uk/record-details?MNF63260", "quote": "The site of a Romano-Celtic temple at Crownthorpe was excavated in 1959.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0048)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia and the Norfolk HER both describe a single Romano-Celtic temple, a cella with a surrounding ambulatory about 16 by 15 m, at the same grid reference (TG 0881 0287). No source describes a precinct or a group of temples, so Temple fits better than Temple complex.", "value_page": null}]'::jsonb),
    ('138ded4c-2d3e-49eb-abe8-e318ba7a37c3'::uuid, 'period_name', NULL, '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s001-rollback:138ded4c-2d3e-49eb-abe8-e318ba7a37c3:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''3000 - 1500 BC'' restored on Axus', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('138ded4c-2d3e-49eb-abe8-e318ba7a37c3'::uuid, 'period_start', NULL, '-2000', 'fields-wd1-2026-09-26b-s001-rollback:138ded4c-2d3e-49eb-abe8-e318ba7a37c3:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-2000'' restored on Axus', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0062)", "decision": "clear", "status": "MISSING", "reasoning": "The sources date the settlement''s beginning only by ceramic phase (Late Minoan IIIC remains per English Wikipedia and Zoeller''s Heidelberg thesis) or disagree (a University of Louvain chapter frames Axos 1200-500 BC, the Mylopotamos municipality dates first habitation ''in the area'' to the late 4th-early 3rd millennium BC); no two independent sources state the same dated start, and none supports the stored -2000, so the field is emptied.", "value_page": null}]'::jsonb),
    ('138ded4c-2d3e-49eb-abe8-e318ba7a37c3'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Axos', 'https://en.wikipedia.org/wiki/Axus', 'fields-wd1-2026-09-26b-s001-rollback:138ded4c-2d3e-49eb-abe8-e318ba7a37c3:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Axus'' restored on Axus', '[{"source": "https://en.wikipedia.org/wiki/Axos", "url": "https://en.wikipedia.org/wiki/Axos", "quote": "also spelled as Axus", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Axos", "url": "https://en.wikipedia.org/wiki/Axos", "quote": "It was an inland town located on the slopes of Mount Ida and its harbour was at Astale", "outcome": "found"}, {"source": "https://imperium.ahlfeldt.se/places/28861.html", "url": "https://imperium.ahlfeldt.se/places/28861.html", "quote": "Information about the ancient place located at Axos", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0062)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL ''Axus'' is a redirect to the English Wikipedia article ''Axos'', which is about this ancient Cretan city (also spelled Axus, harbour at Astale); the Digital Atlas of the Roman Empire records the same ancient place at Axos. The article''s own URL replaces the redirect.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Axos", "unreadable": false, "wikibase_item": "Q2008641"}}]'::jsonb),
    ('14737fca-a885-4a87-aece-42a835e94beb'::uuid, 'period_name', NULL, '< 4500 BC', 'fields-wd1-2026-09-26b-s001-rollback:14737fca-a885-4a87-aece-42a835e94beb:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''< 4500 BC'' restored on Carnedd y Ddelw Cairn', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('14737fca-a885-4a87-aece-42a835e94beb'::uuid, 'period_start', NULL, '-5000', 'fields-wd1-2026-09-26b-s001-rollback:14737fca-a885-4a87-aece-42a835e94beb:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-5000'' restored on Carnedd y Ddelw Cairn', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0153)", "decision": "clear", "status": "MISSING", "reasoning": "Only Cadw dates the cairn with years (probably Bronze Age, c. 2300 - 800 BC); the National Trust record repeats the Cadw text and Coflein and Wikipedia say only Bronze Age without a year, so no second independent dating of the start exists and the stored -5000 (the Bronze Age started c. 2300 BC in Britain) cannot be kept.", "value_page": null}]'::jsonb),
    ('14737fca-a885-4a87-aece-42a835e94beb'::uuid, 'source_url', 'https://coflein.gov.uk/en/sites/303005', 'https://en.wikipedia.org/wiki/Carnedd_y_Ddelw', 'fields-wd1-2026-09-26b-s001-rollback:14737fca-a885-4a87-aece-42a835e94beb:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Carnedd_y_Ddelw'' restored on Carnedd y Ddelw Cairn', '[{"source": "https://coflein.gov.uk/en/sites/303005", "url": "https://coflein.gov.uk/en/sites/303005", "quote": "Carnedd-y-Ddelw", "outcome": "found"}, {"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=1190", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=1190", "quote": "Reference Number CN398 Name Carnedd y Ddelw Cairn", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0153)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the summit; the Coflein record NPRN 303005 (Carnedd-y-Ddelw, type cairn) and Cadw''s scheduled-monument report CN398 (Carnedd y Ddelw Cairn) are about the cairn itself.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('14c0c237-0ece-4124-ada8-8ec56b431b08'::uuid, 'geom', 'SRID=4326;POINT(32.6583 25.7183)', '0101000020E6100000696BE41A06534040E0ACB84F81B63940', 'fields-wd1-2026-09-26b-s001-rollback:14c0c237-0ece-4124-ada8-8ec56b431b08:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E6100000696BE41A06534040E0ACB84F81B63940'' restored on Karnak Temple Complex', '[{"source": "https://en.wikipedia.org/wiki/Karnak", "url": "https://en.wikipedia.org/wiki/Karnak", "quote": "25°43′06″N 32°39′30″E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=10878", "url": "https://www.megalithic.co.uk/article.php?sid=10878", "quote": "Latitude: 25.719440N Longitude: 32.655979E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0023)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia places the Karnak Temple Complex at 25.7183, 32.6583 and the Megalithic Portal places its main monument, the Temple of Amun-Ra, at 25.71944, 32.65598, about 0.27 km apart; the stored point lies about 1.1 km south-west of both, off the precinct in the town towards the Nile, so it is replaced by the complex''s point.", "value_page": null}]'::jsonb),
