    ('14dd917b-b58e-45d6-9578-bc1cefd34728'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s001-rollback:14dd917b-b58e-45d6-9578-bc1cefd34728:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''4500 - 3000 BC'' restored on Mochlos', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('14dd917b-b58e-45d6-9578-bc1cefd34728'::uuid, 'period_start', '-3000', '-3100', 'fields-wd1-2026-09-26b-s001-rollback:14dd917b-b58e-45d6-9578-bc1cefd34728:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-3100'' restored on Mochlos', '[{"source": "https://www.mochlosarchaeologicalproject.org/", "url": "https://www.mochlosarchaeologicalproject.org/", "quote": "It has uncovered remains dating from 3000 BC to the 10th century AD, including a Minoan town of the Neopalatial period (c. 1700-1430 BC), a Mycenaean village and its cemetery (c. 1400-1250 BC), and a Late Hellenistic settlement of the 2nd and 1st centuries BC.", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Mochlos_(Ausgrabungsst%C3%A4tte)", "url": "https://de.wikipedia.org/wiki/Mochlos_(Ausgrabungsst%C3%A4tte)", "quote": "Die ersten Siedler scheinen Mochlos um 3000 v. Chr. von der Kykladeninsel Melos kolonisiert und somit der Kykladenkultur angehört zu haben.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0068)", "decision": "replace", "status": "MISSING", "reasoning": "The excavators'' Mochlos Archaeological Project dates the earliest remains to 3000 BC, and the German Wikipedia article on the site dates the first settlers to about 3000 BC (Early Minoan I); the start therefore falls in 3000 - 1500 BC. The English article''s 3100 BC matches an older project page that dates the Bronze Age occupation of the area ca. 3100-1200 B.C., but the project''s current site gives 3000 BC.", "value_page": null}]'::jsonb),
    ('14dd917b-b58e-45d6-9578-bc1cefd34728'::uuid, 'source_url', 'https://de.wikipedia.org/wiki/Mochlos_(Ausgrabungsst%C3%A4tte)', 'https://en.wikipedia.org/wiki/Mochlos', 'fields-wd1-2026-09-26b-s001-rollback:14dd917b-b58e-45d6-9578-bc1cefd34728:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Mochlos'' restored on Mochlos', '[{"source": "https://de.wikipedia.org/wiki/Mochlos_(Ausgrabungsst%C3%A4tte)", "url": "https://de.wikipedia.org/wiki/Mochlos_(Ausgrabungsst%C3%A4tte)", "quote": "Mochlos (griechisch Μόχλος) ist die Bezeichnung der Ausgrabungsstätte einer von der minoischen bis mit Unterbrechungen in die byzantinische Zeit bestehenden Hafensiedlung in der Gemeinde Sitia im Osten der griechischen Insel Kreta.", "outcome": "found"}, {"source": "https://www.mochlosarchaeologicalproject.org/", "url": "https://www.mochlosarchaeologicalproject.org/", "quote": "The Greek-American excavation at Mochlos, Crete, was begun in 1989 under the auspices of the American School of Classical Studies in Athens", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0068)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English article belongs to the Wikidata item of the islet; the site''s own article is the German Wikipedia article on the Mochlos excavation site (Wikidata Q38281104, ''Mochlos site''), which covers the harbour settlement on the islet and the coast opposite, as the excavation project''s site does too.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Mochlos (Ausgrabungsstätte)", "unreadable": false, "wikibase_item": "Q38281104"}}]'::jsonb),
    ('14f64a8d-97b4-4d86-9b1f-187a126febb8'::uuid, 'geom', 'SRID=4326;POINT(16.362 46.525)', '0101000020E61000008C9306CA496130401B34C3AADA434740', 'fields-wd1-2026-09-26b-s001-rollback:14f64a8d-97b4-4d86-9b1f-187a126febb8:geom', 'rollback of fields-wd1-2026-09-26b-s001: geom ''0101000020E61000008C9306CA496130401B34C3AADA434740'' restored on Halikan', '[{"source": "https://imperium.ahlfeldt.se/places/13836.html", "url": "https://imperium.ahlfeldt.se/places/13836.html", "quote": "46.525, 16.362", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q123823216", "url": "https://www.wikidata.org/wiki/Q123823216", "quote": "46°31''10\"N, 16°21''34\"E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0017)", "decision": "replace", "status": "CONFLICT", "reasoning": "Halicanum lies under the present village of Sveti Martin na Muri, its workshop quarter in the village centre and its residential part further west (Croatian Conservation Institute); the Digital Atlas of the Roman Empire places Halicanum, Sveti Martin na Muri at 46.525, 16.362 and Wikidata at 46.5194, 16.3594, while the stored point lies about 1.5 km east of the village centre.", "value_page": null}]'::jsonb),
