    ('15264f9b-f57b-4562-b577-fbfdec72227f'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s001-rollback:15264f9b-f57b-4562-b577-fbfdec72227f:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1 - 500 AD'' restored on Bokerley Dyke', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('15264f9b-f57b-4562-b577-fbfdec72227f'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s001-rollback:15264f9b-f57b-4562-b577-fbfdec72227f:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1'' restored on Bokerley Dyke', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0027)", "decision": "clear", "status": "MISSING", "reasoning": "The Dorset HER, the Megalithic Portal and Wikipedia say only that Bokerley Dyke ''is thought to have originated in the Bronze Age or Early Iron Age'' (Wikipedia: ''may have''), and the HER adds that ''The chronology of Bokerley Dyke is not certain''; the only dated evidence (1st-century Roman road cutting it, a coin of Valens after AD 364) concerns later phases, and the stored 1 - 500 AD bucket reflects the 4th-century remodelling, so no source dates the start to a year or century and the field is emptied.", "value_page": null}]'::jsonb),
    ('163dc5dd-513c-4dd2-9fd2-87a74fe1078a'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s001-rollback:163dc5dd-513c-4dd2-9fd2-87a74fe1078a:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Fortress/citadel'' restored on Mynydd Carningli', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=3016", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=3016", "quote": "The fort is located on Mynydd Carn Ingli at the eastern end of a high moorland ridge that commands extensive views over the north coast and river valleys to the east and south.", "outcome": "found"}, {"source": "https://coflein.gov.uk/en/sites/300426", "url": "https://coflein.gov.uk/en/sites/300426", "quote": "The great stone hillfort which crowns the scree-strewn summit of Mynydd Carn-ingli remains one of Pembrokeshire''s great mysteries.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0155)", "decision": "replace", "status": "CONFLICT", "reasoning": "Cadw (site type Hillfort) and the RCAHMW Coflein record (NPRN 300426, type HILLFORT) both describe a stone-walled hillfort on the summit; nothing calls it a fortress or citadel, and the item''s summit/hill class is not the site''s type, so the specific canonical type is Fort.", "value_page": null}]'::jsonb),
    ('16818a72-af8e-4397-a814-36c1502b27d3'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s001-rollback:16818a72-af8e-4397-a814-36c1502b27d3:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Fortress/citadel'' restored on Papcastle', '[{"source": "https://en.wikipedia.org/wiki/Derventio_(Papcastle)", "url": "https://en.wikipedia.org/wiki/Derventio_(Papcastle)", "quote": "It was the site of a Roman fort, which was originally built in timber and rebuilt in stone.", "outcome": "found"}, {"source": "https://www.roman-britain.co.uk/places/papcastle/", "url": "https://www.roman-britain.co.uk/places/papcastle/", "quote": "Flavian Auxiliary Fort (AD 69–96)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0042)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Roman-Britain.co.uk describe Derventio at Papcastle as a Roman (auxiliary) fort, not a fortress or citadel, so the specific type is Fort.", "value_page": null}]'::jsonb),
    ('16818a72-af8e-4397-a814-36c1502b27d3'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Derventio_(Papcastle)', 'https://en.wikipedia.org/wiki/Papcastle', 'fields-wd1-2026-09-26b-s001-rollback:16818a72-af8e-4397-a814-36c1502b27d3:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Papcastle'' restored on Papcastle', '[{"source": "https://en.wikipedia.org/wiki/Derventio_(Papcastle)", "url": "https://en.wikipedia.org/wiki/Derventio_(Papcastle)", "quote": "Derventio was a Roman settlement at Papcastle on the river Derwent near Cockermouth, Cumbria, England.", "outcome": "found"}, {"source": "https://www.roman-britain.co.uk/places/papcastle/", "url": "https://www.roman-britain.co.uk/places/papcastle/", "quote": "Papcastle (Derventio) Roman Fort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0042)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the modern village and civil parish; the English Wikipedia article Derventio (Papcastle) is about the Roman fort and settlement itself, which Roman-Britain.co.uk names as Papcastle (Derventio) Roman Fort.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Derventio (Papcastle)", "unreadable": false, "wikibase_item": "Q23042054"}}]'::jsonb),
    ('169edf74-fc91-4850-aa2a-7d5328c13c02'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s001-rollback:169edf74-fc91-4850-aa2a-7d5328c13c02:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''1 - 500 AD'' restored on Intikancha, Puno', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('169edf74-fc91-4850-aa2a-7d5328c13c02'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s001-rollback:169edf74-fc91-4850-aa2a-7d5328c13c02:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''1'' restored on Intikancha, Puno', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia says only that the archaeological site was declared National Cultural Heritage, without a date. The Wikidata dates belong to the mountain, and no readable independent source dates the site, so the field is cleared.", "value_page": null}]'::jsonb),
    ('169edf74-fc91-4850-aa2a-7d5328c13c02'::uuid, 'site_type', NULL, 'City/town/settlement', 'fields-wd1-2026-09-26b-s001-rollback:169edf74-fc91-4850-aa2a-7d5328c13c02:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''City/town/settlement'' restored on Intikancha, Puno', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "clear", "status": "CONFLICT", "reasoning": "The readable sources (English and Spanish Wikipedia and pages copying them) say only that there is an archaeological site of the same name on the mountain. Nothing readable describes it as a city, town or settlement, and the fortified-outpost description sits behind closed-access journal pages, so the field is cleared.", "value_page": null}]'::jsonb),
    ('169edf74-fc91-4850-aa2a-7d5328c13c02'::uuid, 'source_url', NULL, 'https://en.wikipedia.org/wiki/Intikancha_(Puno)', 'fields-wd1-2026-09-26b-s001-rollback:169edf74-fc91-4850-aa2a-7d5328c13c02:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Intikancha_(Puno)'' restored on Intikancha, Puno', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "clear", "status": "CONFLICT", "reasoning": "The English Wikipedia stub is mainly about the mountain, with one line on the heritage declaration of the archaeological site. No independent readable page names the site to confirm a source, since every other readable page copies Wikipedia and the scholarly papers are closed or refuse automated requests. The field is therefore cleared.", "value_page": null}]'::jsonb),
    ('16d660a1-92c1-4853-ad87-7d6979ce47cd'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s001-rollback:16d660a1-92c1-4853-ad87-7d6979ce47cd:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''4500 - 3000 BC'' restored on Pinnacle Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('16d660a1-92c1-4853-ad87-7d6979ce47cd'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s001-rollback:16d660a1-92c1-4853-ad87-7d6979ce47cd:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-4500'' restored on Pinnacle Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0043)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and Geograph only call the two mounds possible Bronze Age round barrows; no readable source gives a year, century or millennium for their construction, and the stored Neolithic-bucket value -4500 is unsupported, so the field is emptied.", "value_page": null}]'::jsonb),
    ('16d71206-b1bd-4575-85b9-14567a8c1c4e'::uuid, 'site_type', 'Fortification', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s001-rollback:16d71206-b1bd-4575-85b9-14567a8c1c4e:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Fortress/citadel'' restored on Khotiv Hillfort', '[{"source": "https://en.wikipedia.org/wiki/Khotiv_hillfort", "url": "https://en.wikipedia.org/wiki/Khotiv_hillfort", "quote": "These boundaries embraced the plateau with the fortification and adjacent slopes", "outcome": "found"}, {"source": "https://funtime.com.ua/art-and-culture/khotivske-horodyshche", "url": "https://funtime.com.ua/art-and-culture/khotivske-horodyshche", "quote": "Воно вважається найпівнічнішим відомим скіфським укріпленням.", "outcome": "found"}, {"source": "https://pamyatky.kiev.ua/articles/istorichni-statti/hotivske-gorodishche-kin-65-st-do-n-e", "url": "https://pamyatky.kiev.ua/articles/istorichni-statti/hotivske-gorodishche-kin-65-st-do-n-e", "quote": "Городище мало замкнену систему захисту у вигляді валу", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0151)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe a Scythian-era hillfort: a 31 ha plateau enclosed by a rampart, scarp, berm and moat, ''the northernmost known Scythian fortification'' (funtime.com.ua); none calls it a fortress or citadel (Antonovych''s ''fortress Zvenigorod'' was refuted), so the fitting canonical type is Fortification.", "value_page": null}]'::jsonb),
    ('17191c2e-9ebc-41e5-865f-1bb6be790eb5'::uuid, 'site_type', 'Village', 'City/town/settlement', 'fields-wd1-2026-09-26b-s001-rollback:17191c2e-9ebc-41e5-865f-1bb6be790eb5:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''City/town/settlement'' restored on Broch of Gurness', '[{"source": "https://en.wikipedia.org/wiki/Broch_of_Gurness", "url": "https://en.wikipedia.org/wiki/Broch_of_Gurness", "quote": "The Broch of Gurness is an Iron Age broch village on the northeast coast of Mainland Orkney in Scotland overlooking Eynhallow Sound, about 15 miles north-west of Kirkwall.", "outcome": "found"}, {"source": "https://www.historicenvironment.scot/visit/all/broch-of-gurness/history-and-stories/", "url": "https://www.historicenvironment.scot/visit/all/broch-of-gurness/history-and-stories/", "quote": "The village at Gurness is the best-preserved of all broch villages.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0122)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both Wikipedia and Historic Environment Scotland describe the site as an Iron Age broch village - a broch tower with a village of stone houses around it inside ditches; the most specific canonical type that holds is Village, more specific than the stored City/town/settlement, while tower or fort would describe only its central building.", "value_page": null}]'::jsonb),
    ('17483f6c-6a12-4652-83e1-e0a2f6665429'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s001-rollback:17483f6c-6a12-4652-83e1-e0a2f6665429:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 BC - 1 AD'' restored on Juhor', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('17483f6c-6a12-4652-83e1-e0a2f6665429'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s001-rollback:17483f6c-6a12-4652-83e1-e0a2f6665429:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-500'' restored on Juhor', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0125)", "decision": "clear", "status": "MISSING", "reasoning": "The site does not begin in 500 BC - 1 AD. The Serbian Encyclopedia dates the oldest material from the Veliki Vetren settlement to the Eneolithic and calls it continuously inhabited; turistickiklub.com and izbenica.com put the oldest traces in the (mid-)5th millennium, and the Celtic fort in the 2nd century BC. No source states that Eneolithic start as a readable BC year or millennium, so the field is emptied rather than kept wrong.", "value_page": null}]'::jsonb),
    ('17483f6c-6a12-4652-83e1-e0a2f6665429'::uuid, 'site_type', 'Fort', 'Archaeological site', 'fields-wd1-2026-09-26b-s001-rollback:17483f6c-6a12-4652-83e1-e0a2f6665429:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Archaeological site'' restored on Juhor', '[{"source": "https://oldeuropeanculture.blogspot.com/2020/10/veliki-vetren.html", "url": "https://oldeuropeanculture.blogspot.com/2020/10/veliki-vetren.html", "quote": "The further digs in the area discovered that the whole top of the Veliki Vetren peak was fortified and turned into a Celtic oppidum.", "outcome": "found"}, {"source": "https://srpskaenciklopedija.rs/books/slovo-v/page/veliki-vetren", "url": "https://srpskaenciklopedija.rs/books/slovo-v/page/veliki-vetren", "quote": "констатовано је постојање утврђења, површине 4 ха, опасаног зидинама од камена и земље", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0023)", "decision": "replace", "status": "CONFLICT", "reasoning": "The archaeological site on Juhor is the Veliki Vetren summit, not the mountain: the Serbian Encyclopedia records a 4 ha fortification ringed by stone-and-earth walls with an outer settlement, and an English account of the excavations says the whole peak top was fortified as a Celtic oppidum. A walled Late Iron Age hill fort is a Fort; the stored ''Archaeological site'' is only the generic fallback.", "value_page": null}]'::jsonb),
    ('17483f6c-6a12-4652-83e1-e0a2f6665429'::uuid, 'source_url', NULL, 'https://en.wikipedia.org/wiki/Juhor', 'fields-wd1-2026-09-26b-s001-rollback:17483f6c-6a12-4652-83e1-e0a2f6665429:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Juhor'' restored on Juhor', '[{"source": "WD1 decision (exhausted, round 2, None)", "decision": "clear", "status": "CONFLICT", "reasoning": "no counted answer in 3 rounds: quote not found: https://www.turistickiklub.com/sadrzaj/veliki-vetren; quote not found: https://www.turistickiklub.com/sadrzaj/veliki-vetren; quote not found: https://www.turistickiklub.com/sadrzaj/veliki-vetren", "value_page": null}]'::jsonb),
    ('179f8253-8391-4278-b03c-c905df8f6818'::uuid, 'period_name', '3000 - 1500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s001-rollback:179f8253-8391-4278-b03c-c905df8f6818:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''500 BC - 1 AD'' restored on Poundbury Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('179f8253-8391-4278-b03c-c905df8f6818'::uuid, 'period_start', '-3000', '-500', 'fields-wd1-2026-09-26b-s001-rollback:179f8253-8391-4278-b03c-c905df8f6818:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-500'' restored on Poundbury Hill', '[{"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO18391", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO18391", "quote": "UNENCLOSED SETTLEMENT? (Late Neolithic - 3000 BC to 2351 BC)", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/modules.php?op=modload&name=a312&file=index&do=showpic&pid=272316", "url": "https://www.megalithic.co.uk/modules.php?op=modload&name=a312&file=index&do=showpic&pid=272316", "quote": "It includes evidence of a Neolithic settlement of the 3rd millennium BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0007)", "decision": "replace", "status": "MISSING", "reasoning": "Poundbury Hill is a multi-period site whose first occupation is a Late Neolithic settlement: the Dorset Historic Environment Record dates the Poundbury Late Neolithic settlement to 3000 BC-2351 BC, and the scheduling text (reproduced on the Megalithic Portal page) speaks of a Neolithic settlement of the 3rd millennium BC, so the start is -3000, well before the stored -500 (the Iron Age hillfort phase came later).", "value_page": null}]'::jsonb),
    ('179f8253-8391-4278-b03c-c905df8f6818'::uuid, 'site_type', 'Fort', 'City/town/settlement', 'fields-wd1-2026-09-26b-s001-rollback:179f8253-8391-4278-b03c-c905df8f6818:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''City/town/settlement'' restored on Poundbury Hill', '[{"source": "https://en.wikipedia.org/wiki/Poundbury_Hill", "url": "https://en.wikipedia.org/wiki/Poundbury_Hill", "quote": "Hill fort in Dorset, England", "outcome": "found"}, {"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO1057", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO1057", "quote": "Earthwork remains of an Iron Age bivallate hillfort, visible on aerial photographs.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=1500", "url": "https://www.megalithic.co.uk/article.php?sid=1500", "quote": "Site Name: Poundbury Country: England County: Dorset Type: Hillfort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0043)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, the Dorset Historic Environment Record (''Poundbury hillfort, Dorchester'') and the Megalithic Portal all describe Poundbury Hill as an Iron Age hillfort, the monument at the centre of the scheduled complex; it was never a town, so Fort replaces City/town/settlement.", "value_page": null}]'::jsonb),
    ('17c015fb-6576-4edd-be5f-b07d6f89c235'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Argi%C5%A1ti%E1%B8%ABinili', 'https://en.wikipedia.org/wiki/Argishtikhinili_(ancient_city)', 'fields-wd1-2026-09-26b-s001-rollback:17c015fb-6576-4edd-be5f-b07d6f89c235:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Argishtikhinili_(ancient_city)'' restored on Ancient City of Argishtikhinili', '[{"source": "https://en.wikipedia.org/wiki/Argi%C5%A1ti%E1%B8%ABinili", "url": "https://en.wikipedia.org/wiki/Argi%C5%A1ti%E1%B8%ABinili", "quote": "The ruins of the Argištiḫinili fortifications are 15 kilometres (9 mi) southwest of the present-day town of Armavir", "outcome": "found"}, {"source": "https://archaeologymag.com/2026/05/hidden-hydraulic-system-argishtikhinili-armenia/", "url": "https://archaeologymag.com/2026/05/hidden-hydraulic-system-argishtikhinili-armenia/", "quote": "Argishtikhinili, one of the major urban centers of Urartu, stood near present-day Armavir in western Armenia.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a redirect to the English Wikipedia article Argištiḫinili, which is about this Urartian town; the article''s own URL replaces the redirect.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Argištiḫinili", "unreadable": false, "wikibase_item": "Q675636"}}]'::jsonb),
    ('17c94d52-2df2-44ba-83f1-41c26ee6eea3'::uuid, 'site_type', 'City', 'Temple complex', 'fields-wd1-2026-09-26b-s001-rollback:17c94d52-2df2-44ba-83f1-41c26ee6eea3:site_type', 'rollback of fields-wd1-2026-09-26b-s001: site_type ''Temple complex'' restored on Butrint', '[{"source": "https://en.wikipedia.org/wiki/Butrint", "url": "https://en.wikipedia.org/wiki/Butrint", "quote": "was an ancient Greek polis and later Roman city and the seat of an early Christian bishopric in Epirus.", "outcome": "found"}, {"source": "https://site.unibo.it/butrint/en/atlas-and-history/history-of-the-city", "url": "https://site.unibo.it/butrint/en/atlas-and-history/history-of-the-city", "quote": "The favourable position in which the city of Buthrotum was born and developed, in the ancient region of Chaonia, can explain the long occupation of the site (almost 200 ha)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the University of Bologna''s Butrint Project describe Butrint as an ancient city (Greek polis, then Roman city); it is not a temple complex, though it contains sanctuaries.", "value_page": null}]'::jsonb),
    ('1803a375-2b6b-4335-b158-98a371ce8889'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s001-rollback:1803a375-2b6b-4335-b158-98a371ce8889:period_name', 'rollback of fields-wd1-2026-09-26b-s001: period_name ''4500 - 3000 BC'' restored on Merrivale, Devon', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2500) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1803a375-2b6b-4335-b158-98a371ce8889'::uuid, 'period_start', '-2500', '-4000', 'fields-wd1-2026-09-26b-s001-rollback:1803a375-2b6b-4335-b158-98a371ce8889:period_start', 'rollback of fields-wd1-2026-09-26b-s001: period_start ''-4000'' restored on Merrivale, Devon', '[{"source": "https://visitdartmoor.co.uk/things-to-do/moors-tors/merrivale-stone-rows/", "url": "https://visitdartmoor.co.uk/things-to-do/moors-tors/merrivale-stone-rows/", "quote": "The monuments were probably built over a long period of time in the Bronze Age, between 2500BC and 1000BC", "outcome": "found"}, {"source": "https://www.english-heritage.org.uk/visit/places/merrivale-prehistoric-settlement/history/", "url": "https://www.english-heritage.org.uk/visit/places/merrivale-prehistoric-settlement/history/", "quote": "The monuments from the late Neolithic (3000–2300 BC) here comprise two double stone rows, a single row, a small stone circle", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0007)", "decision": "replace", "status": "MISSING", "reasoning": "The Merrivale monuments (stone rows, circle, cairns) on Dartmoor are not dated to 4500-3000 BC: Visit Dartmoor dates their building to the Bronze Age from 2500 BC, and English Heritage, which cares for the site, dates the ritual monuments to the late Neolithic (3000-2300 BC) and the settlement to the Bronze Age; both fall in the 3000-1500 BC bucket and -2500 lies within both statements.", "value_page": null}]'::jsonb),
    ('1803a375-2b6b-4335-b158-98a371ce8889'::uuid, 'source_url', 'https://de.wikipedia.org/wiki/Merrivale', 'https://en.wikipedia.org/wiki/Merrivale,_Devon', 'fields-wd1-2026-09-26b-s001-rollback:1803a375-2b6b-4335-b158-98a371ce8889:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Merrivale,_Devon'' restored on Merrivale, Devon', '[{"source": "https://de.wikipedia.org/wiki/Merrivale", "url": "https://de.wikipedia.org/wiki/Merrivale", "quote": "Der Megalithkomplex von Merrivale (auch Merivale) liegt in West-Devon, im Dartmoor National Park nahe der B3357 bei Tavistock", "outcome": "found"}, {"source": "https://www.english-heritage.org.uk/visit/places/merrivale-prehistoric-settlement/", "url": "https://www.english-heritage.org.uk/visit/places/merrivale-prehistoric-settlement/", "quote": "Dartmoor is rich in prehistoric remains, and the group of monuments at Merrivale is one of the finest on the moor.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0041)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English article is about the hamlet; the German Wikipedia article ''Merrivale'' is about the megalithic complex itself, and English Heritage names the same monument group, so the German article is the site''s own page.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Merrivale", "unreadable": false, "wikibase_item": "Q1922050"}}]'::jsonb),
    ('180e049b-1586-4a75-8e85-8d771fe7ba69'::uuid, 'source_url', NULL, 'https://en.wikipedia.org/wiki/Glubochek', 'fields-wd1-2026-09-26b-s001-rollback:180e049b-1586-4a75-8e85-8d771fe7ba69:source_url', 'rollback of fields-wd1-2026-09-26b-s001: source_url ''https://en.wikipedia.org/wiki/Glubochek'' restored on Glubochek', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0150)", "decision": "clear", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article Glubochek does not exist any more (the API reports it missing; Hlybochok is only a disambiguation page and the village articles are about villages). The settlement is a scholarly subject under the spelling Hlybochok (e.g. the Arheologia 2021 article page https://arheologia.com.ua/index.php/arheologia/article/view/286), but I found no readable page about this very site that uses the entry''s name Glubochek together with an independent second source, only Wikipedia mirrors and an AI-generated encyclopedia copy, which I do not cite, so the dead link is emptied.", "value_page": null}]'::jsonb);
